// questions-identity-logins.js
// Cyber Defense Runner - Identity & Logins question bank (100 questions).
// Standalone data file. NOT yet merged into questions.js.
// Distribution: tiers 50 Beginner / 35 Intermediate / 15 Advanced.
//               correct index balanced 25 / 25 / 25 / 25 across A/B/C/D.

const IDENTITY_LOGINS_QUESTIONS = [
  { id:"identity-logins-001", tier:"Beginner", topic:"Identity & Logins", prompt:"What does authentication verify?", options:["Who you are (your identity)","How fast your internet is","The color of your screen","The size of your disk"], correct:0, explain:"Authentication confirms a user's identity, usually via a password or another factor.", reward:"Auth Basics" },
  { id:"identity-logins-002", tier:"Beginner", topic:"Identity & Logins", prompt:"What does authorization decide?", options:["How fast your internet connection is","What an authenticated user is allowed to do","Which wallpaper image is shown","What font size the screen uses"], correct:1, explain:"Authorization determines which actions and resources an identity is permitted to use.", reward:"Authz Sense" },
  { id:"identity-logins-003", tier:"Beginner", topic:"Identity & Logins", prompt:"What does MFA (multi-factor authentication) require?", options:["Only a single account password by itself","Only your username on its own","Nothing at all is ever really needed","More than one type of proof, like a password plus a code"], correct:3, explain:"MFA requires two or more different factors, making a stolen password alone insufficient.", reward:"MFA Shield" },
  { id:"identity-logins-004", tier:"Beginner", topic:"Identity & Logins", prompt:"Which makes a password stronger?", options:["Putting your own name in it","Choosing something like '12345'","Length and unpredictability","Picking a single short word"], correct:2, explain:"Longer, unpredictable passwords are much harder to guess or crack.", reward:"Password Strength" },
  { id:"identity-logins-005", tier:"Beginner", topic:"Identity & Logins", prompt:"What does a password manager do?", options:["Speeds up the internet","Securely stores and fills your passwords","Cools the CPU","Designs websites"], correct:1, explain:"A password manager securely stores unique passwords and fills them in for you.", reward:"Manager Habit" },
  { id:"identity-logins-006", tier:"Beginner", topic:"Identity & Logins", prompt:"What does an account lockout policy do?", options:["Temporarily blocks logins after too many failed attempts","Permanently speeds up each login","Deletes the user's whole account","Changes the account's password"], correct:0, explain:"Lockout pauses access after repeated failures, slowing password-guessing attacks.", reward:"Lockout Sense" },
  { id:"identity-logins-007", tier:"Beginner", topic:"Identity & Logins", prompt:"What does 'privilege' mean for a user account?", options:["How big the account's screen is","How fast the account can type","The level of access and actions it is allowed","Which color the account displays"], correct:2, explain:"Privilege is the access level an account has, such as standard user versus administrator.", reward:"Privilege Sense" },
  { id:"identity-logins-008", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a 'role' in access management?", options:["A speaking part in a movie or play","A particular display screen setting","A secret password for an account","A named set of permissions assigned to users by job function"], correct:3, explain:"A role bundles permissions by job function, simplifying who-can-do-what.", reward:"Role Sense" },
  { id:"identity-logins-009", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a 'group' in identity management?", options:["A collection of users managed together for access","A particular type of network cable","A routine scheduled data backup","A secret password for an account"], correct:0, explain:"A group bundles users so permissions can be granted to many people at once.", reward:"Group Sense" },
  { id:"identity-logins-010", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a 'service account'?", options:["A human user's own personal login","A non-human account used by an application or service","A routine backup file kept on disk","A particular type of network firewall"], correct:1, explain:"Service accounts are used by software or services to run tasks, not by people directly.", reward:"Service Account Care" },
  { id:"identity-logins-011", tier:"Beginner", topic:"Identity & Logins", prompt:"What does OAuth let you do?", options:["Cool down the whole computer's main CPU","Design a brand-new company logo image file","Back up the entire contents of a whole disk","Grant an app limited access to your account without sharing your password"], correct:3, explain:"OAuth lets you authorize an app to access certain data without giving it your password.", reward:"OAuth Sense" },
  { id:"identity-logins-012", tier:"Beginner", topic:"Identity & Logins", prompt:"What does Single Sign-On (SSO) allow?", options:["A much faster internet connection","Noticeably brighter monitor screens","Logging into many apps with one set of credentials","Much bigger storage disks"], correct:2, explain:"SSO lets users access multiple applications after a single login.", reward:"SSO Sense" },
  { id:"identity-logins-013", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a login 'session'?", options:["A recorded music audio track file","A period where you stay logged in after authenticating","A routine scheduled data backup","A secret password for an account"], correct:1, explain:"A session keeps you authenticated for a time so you don't re-login on every action.", reward:"Session Sense" },
  { id:"identity-logins-014", tier:"Beginner", topic:"Identity & Logins", prompt:"What is an authentication 'token'?", options:["A piece of data proving you're authenticated, used instead of resending your password","A small round metal coin you can hold in your hand","A physical network connection cable used for data","A computer display monitor screen sitting on a desk"], correct:0, explain:"Tokens represent an authenticated session so apps don't pass the password repeatedly.", reward:"Token Sense" },
  { id:"identity-logins-015", tier:"Beginner", topic:"Identity & Logins", prompt:"What is 'credential theft'?", options:["A routine scheduled backup process","One single firewall configuration rule","Stealing usernames, passwords, or tokens to access accounts","Applying a small software patch"], correct:2, explain:"Credential theft is obtaining login secrets to impersonate users and access systems.", reward:"Credential Guard" },
  { id:"identity-logins-016", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a brute-force login attack?", options:["Running a routine data backup","Applying a software security patch","Configuring a network firewall","Trying many passwords rapidly until one works"], correct:3, explain:"Brute force systematically guesses many passwords to find a working one.", reward:"Guess Defense" },
  { id:"identity-logins-017", tier:"Beginner", topic:"Identity & Logins", prompt:"What is 'password spraying'?", options:["Trying one or a few common passwords across many accounts","Running a routine data backup job","Configuring a new network firewall","Applying a small software patch"], correct:0, explain:"Spraying tries a few common passwords against many accounts to avoid per-account lockouts.", reward:"Spray Defense" },
  { id:"identity-logins-018", tier:"Beginner", topic:"Identity & Logins", prompt:"What does 'least privilege' mean for logins?", options:["Give everyone admin","Give each account only the access it needs","Give no access at all","Share accounts"], correct:1, explain:"Least privilege grants the minimum access required, limiting damage from misuse.", reward:"Least Privilege" },
  { id:"identity-logins-019", tier:"Beginner", topic:"Identity & Logins", prompt:"What is 'conditional access'?", options:["Running a routine scheduled data backup overnight","Configuring a brand-new network firewall rule","Choosing a strong password for the account","Allowing or blocking logins based on conditions like location, device, or risk"], correct:3, explain:"Conditional access applies rules such as location, device health, and risk to decide whether to allow a login.", reward:"Conditional Sense" },
  { id:"identity-logins-020", tier:"Beginner", topic:"Identity & Logins", prompt:"Why monitor login activity?", options:["Mainly to produce nicer charts","To deliberately slow down logins","To spot suspicious or unauthorized access attempts","To end up using more storage"], correct:2, explain:"Watching logins helps detect compromised accounts and intrusion attempts early.", reward:"Login Watch" },
  { id:"identity-logins-021", tier:"Beginner", topic:"Identity & Logins", prompt:"Which is an example of authentication?", options:["Choosing a wallpaper","Logging in with a username and password","Resizing a window","Charging a phone"], correct:1, explain:"Providing a username and password to prove identity is authentication.", reward:"Auth Basics" },
  { id:"identity-logins-022", tier:"Intermediate", topic:"Identity & Logins", prompt:"A user logs in successfully but can't open the payroll folder. This is controlled by...?", options:["Authorization (their permissions)","Their monitor","Their keyboard","The weather"], correct:0, explain:"Being authenticated doesn't grant everything; authorization controls access to specific resources.", reward:"Authz Sense" },
  { id:"identity-logins-023", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why does MFA help even if your password is stolen?", options:["MFA speeds up each login attempt","MFA simply hides your username","The attacker still lacks the second factor","It deletes the old account password"], correct:2, explain:"Without the additional factor, a stolen password alone won't grant access.", reward:"MFA Shield" },
  { id:"identity-logins-024", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is reusing the same password everywhere risky?", options:["Reused passwords are slower","Reused passwords look bad","It uses up more memory","One breach can expose all of your accounts"], correct:3, explain:"If a reused password leaks, attackers can access every account that shares it.", reward:"Password Strength" },
  { id:"identity-logins-025", tier:"Intermediate", topic:"Identity & Logins", prompt:"How does a password manager help security?", options:["It makes it practical to use a unique strong password for every site","It deletes all of your old accounts","It shares your passwords publicly online","It quietly disables your MFA protection"], correct:0, explain:"By remembering many strong unique passwords, it removes the temptation to reuse weak ones.", reward:"Manager Habit" },
  { id:"identity-logins-026", tier:"Beginner", topic:"Identity & Logins", prompt:"How does account lockout help against brute-force attacks?", options:["It encrypts the whole monitor screen","It limits how many password guesses an attacker can make","It speeds up the computer's main CPU","It hides the account's login username"], correct:1, explain:"By capping failed attempts, lockout stops attackers from guessing endlessly.", reward:"Lockout Sense" },
  { id:"identity-logins-027", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why are administrator (privileged) accounts high-value targets?", options:["They are generally quite colorful","They can type a lot faster","They use up less server power","They can make wide-reaching changes attackers want"], correct:3, explain:"Admin accounts can change systems broadly, so attackers prize them.", reward:"Privilege Sense" },
  { id:"identity-logins-028", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is role-based access control (RBAC) useful?", options:["It is generally quite colorful to look at","It is much faster to type out fully by hand","It grants permissions by role, keeping access consistent and manageable","It uses up a whole lot less disk space"], correct:2, explain:"RBAC assigns access by role, making permissions consistent and easier to manage.", reward:"Role Sense" },
  { id:"identity-logins-029", tier:"Beginner", topic:"Identity & Logins", prompt:"Why assign access to a group rather than each user individually?", options:["Mainly to give it some much nicer names","Adding or removing a user from the group updates their access easily","To deliberately slow down all the logins","To end up using much more storage space"], correct:1, explain:"Group membership makes granting and revoking access to many users simple and consistent.", reward:"Group Sense" },
  { id:"identity-logins-030", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should service accounts follow least privilege?", options:["They often run unattended, so limiting access reduces risk if abused","They can type out a whole lot faster","They generally end up looking a lot nicer","They use up far less overall server power"], correct:0, explain:"Unattended service accounts with excess rights are risky if compromised, so scope them tightly.", reward:"Service Account Care" },
  { id:"identity-logins-031", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is OAuth safer than giving an app your actual password?", options:["OAuth is generally quite a lot faster","OAuth tokens tend to look more colorful","The app gets a limited, revocable token instead of your password","It uses up a whole lot less mobile data"], correct:2, explain:"OAuth issues a scoped token you can revoke, rather than exposing your real password.", reward:"OAuth Sense" },
  { id:"identity-logins-032", tier:"Intermediate", topic:"Identity & Logins", prompt:"A security benefit of SSO is...?", options:["Many more passwords for users to remember","Generally much slower user logins overall","Random and inconsistent access for users","Fewer passwords to manage and a central place to enforce policy and MFA"], correct:3, explain:"SSO reduces password sprawl and centralizes controls like MFA and access policy.", reward:"SSO Sense" },
  { id:"identity-logins-033", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why do sessions usually expire after inactivity?", options:["To limit the risk if a device is left unattended or a session is stolen","Mainly to help save some extra battery power","Mainly to give it some much nicer themes","To deliberately slow down all the logins"], correct:0, explain:"Expiring idle sessions reduces the chance of misuse on unattended or hijacked sessions.", reward:"Session Sense" },
  { id:"identity-logins-034", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should access tokens be kept secret?", options:["Hidden tokens simply look a bit nicer","Anyone with the token could act as the authenticated user","Secret tokens load noticeably faster","They use up less overall server memory"], correct:1, explain:"A stolen token can be used to impersonate the user, so tokens must be protected.", reward:"Token Sense" },
  { id:"identity-logins-035", tier:"Beginner", topic:"Identity & Logins", prompt:"Which is a common way credentials get stolen?", options:["Patching the company's main servers","Backing up important company data","Encrypting all of the system disks","Phishing emails that trick users into entering passwords"], correct:3, explain:"Phishing is a leading method of stealing credentials by tricking users into revealing them.", reward:"Credential Guard" },
  { id:"identity-logins-036", tier:"Intermediate", topic:"Identity & Logins", prompt:"Which most directly slows a brute-force login attack?", options:["Switching to a brighter screen","Installing a faster CPU","Lockouts and rate limiting on failed attempts","Adding much more disk space"], correct:2, explain:"Limiting and delaying failed attempts stops attackers from guessing endlessly.", reward:"Guess Defense" },
  { id:"identity-logins-037", tier:"Intermediate", topic:"Identity & Logins", prompt:"How does password spraying evade simple lockout defenses?", options:["By encrypting all of its own network traffic","By trying only a few passwords per account, staying under lockout limits","By simply going a whole lot faster overall","By hiding the entire login screen completely"], correct:1, explain:"Few guesses per account keep spraying below lockout thresholds.", reward:"Spray Defense" },
  { id:"identity-logins-038", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why does least privilege reduce the impact of a compromised account?", options:["A limited account can reach and harm less","Such accounts speed up login","Such accounts change the colors","It uses up more storage space"], correct:0, explain:"If a low-privilege account is compromised, the attacker can do less with it.", reward:"Least Privilege" },
  { id:"identity-logins-039", tier:"Beginner", topic:"Identity & Logins", prompt:"Which is an example of a conditional access rule?", options:["Brighten the whole monitor screen","Cool down the computer's main CPU","Require MFA when logging in from an unfamiliar location","Delete all of the system logs"], correct:2, explain:"Requiring extra verification from unusual locations is a common conditional access rule.", reward:"Conditional Sense" },
  { id:"identity-logins-040", tier:"Intermediate", topic:"Identity & Logins", prompt:"Which login event is most worth investigating?", options:["A normal 9am login from the office computer","A routine password autofill on a known site","Opening a previously saved browser bookmark","A successful login right after many failures, from a new location"], correct:3, explain:"A success following many failures from an unusual place can indicate a break-in.", reward:"Login Watch" },
  { id:"identity-logins-041", tier:"Advanced", topic:"Identity & Logins", prompt:"What is the difference between authentication and authorization?", options:["Authentication proves who you are; authorization decides what you may do","They are both completely identical things","Authentication just sets the screen colors","Authorization simply proves your identity"], correct:0, explain:"Authentication verifies identity; authorization determines the permissions that identity has.", reward:"Auth Basics" },
  { id:"identity-logins-042", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should authorization be enforced on the server, not just hidden in the UI?", options:["Mainly just to get some nicer-looking buttons on screen","Hiding a button doesn't stop a determined user; the server must enforce access","To speed the whole thing up quite a bit","To help the server save some battery power"], correct:1, explain:"UI hiding is not security; the server must enforce who can do what.", reward:"Authz Sense" },
  { id:"identity-logins-043", tier:"Intermediate", topic:"Identity & Logins", prompt:"Which is an example of a second factor in MFA?", options:["A second password","Your username again","Your email address","A one-time code from an app or device"], correct:3, explain:"A one-time code from an authenticator app or device is a separate factor (something you have).", reward:"MFA Shield" },
  { id:"identity-logins-044", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is a long passphrase often better than a short complex password?", options:["Passphrases are generally a bit prettier to read","Passphrases can be typed in faster","Length adds far more possible combinations and is easier to remember","It uses up less overall server memory"], correct:2, explain:"Length dramatically increases guessing difficulty while passphrases stay memorable.", reward:"Password Strength" },
  { id:"identity-logins-045", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is the password manager's master password so important?", options:["It simply changes the screen display colors","It unlocks all stored passwords, so it must be strong and protected","It speeds up all of your daily typing","It is generally completely optional anyway"], correct:1, explain:"The master password guards the whole vault, so it should be strong and never reused.", reward:"Manager Habit" },
  { id:"identity-logins-046", tier:"Advanced", topic:"Identity & Logins", prompt:"A downside of overly aggressive account lockout settings is...?", options:["They can lock out legitimate users or be abused to deliberately lock people out","Noticeably faster everyday user logins overall","Much brighter and far clearer monitor screens","Quite a lot more free disk storage space here"], correct:0, explain:"Too-strict lockouts can frustrate real users and be abused to lock people out on purpose.", reward:"Lockout Sense" },
  { id:"identity-logins-047", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why use a standard account for everyday work instead of an admin account?", options:["Standard accounts are generally faster","Standard accounts simply look nicer","If compromised, the damage is limited to standard-user actions","It uses up less disk space overall"], correct:2, explain:"Daily use of a non-admin account limits harm if that account is compromised.", reward:"Privilege Sense" },
  { id:"identity-logins-048", tier:"Intermediate", topic:"Identity & Logins", prompt:"When an employee changes jobs internally, their roles should be...?", options:["Left exactly as they are forever","Doubled in size for some reason","Completely ignored every single time","Updated to match the new job, removing old access"], correct:3, explain:"Updating roles on a job change prevents lingering, unneeded access (privilege creep).", reward:"Role Sense" },
  { id:"identity-logins-049", tier:"Beginner", topic:"Identity & Logins", prompt:"Why review group memberships periodically?", options:["To remove users who no longer need that access","To change the display colors","To speed up the computer's CPU","To end up using more disk space"], correct:0, explain:"Regular reviews catch stale memberships that grant access people no longer need.", reward:"Group Sense" },
  { id:"identity-logins-050", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why are unused or forgotten service accounts a risk?", options:["They generally look quite messy and untidy","They may keep broad access and go unmonitored, making good attack targets","They are generally rather slow to actually use","They use up a whole lot more storage space"], correct:1, explain:"Stale service accounts can retain access and escape monitoring, attracting attackers.", reward:"Service Account Care" },
  { id:"identity-logins-051", tier:"Advanced", topic:"Identity & Logins", prompt:"An app requests far more permissions than it needs via OAuth. You should...?", options:["Just always allow it anyway","Allow it and then simply ignore it","Approve it very quickly without thinking","Be cautious, since over-broad access could be misused"], correct:3, explain:"Granting excessive OAuth scopes risks misuse; review what an app actually needs.", reward:"OAuth Sense" },
  { id:"identity-logins-052", tier:"Advanced", topic:"Identity & Logins", prompt:"A risk to manage with SSO is...?", options:["Having far too many fonts to pick from","Generally quite slow typing for users","If the SSO account is compromised, many apps could be exposed","Overly bright monitor screens everywhere"], correct:2, explain:"Because SSO unlocks many apps, its account must be strongly protected, for example with MFA.", reward:"SSO Sense" },
  { id:"identity-logins-053", tier:"Beginner", topic:"Identity & Logins", prompt:"Why log out of shared or public computers?", options:["Mainly to get nicer-looking screens","So the next user can't continue your session","To speed up the computer's CPU","To save some extra storage space"], correct:1, explain:"Logging out ends your session so others on that device can't access your account.", reward:"Session Sense" },
  { id:"identity-logins-054", tier:"Advanced", topic:"Identity & Logins", prompt:"Why do many tokens have a short expiry time?", options:["So a stolen token is only useful for a limited window","Mainly to help save some power","Mainly for a nicer-looking display","To deliberately slow the apps down"], correct:0, explain:"Short-lived tokens limit how long a leaked token can be abused.", reward:"Token Sense" },
  { id:"identity-logins-055", tier:"Intermediate", topic:"Identity & Logins", prompt:"After a credential-theft incident, a key remediation step is to...?", options:["Just ignore the whole incident entirely","Simply do nothing at all about it now","Reset affected passwords and review the account's recent activity","Share the passwords with other people"], correct:2, explain:"Reset compromised credentials and review what the account did to contain the theft.", reward:"Credential Guard" },
  { id:"identity-logins-056", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why are short, simple passwords weak against brute force?", options:["Such passwords are quite colorful","Such passwords load very slowly","They use up more server memory","There are few combinations, so they are guessed quickly"], correct:3, explain:"Few possible combinations make short, simple passwords fast to crack.", reward:"Guess Defense" },
  { id:"identity-logins-057", tier:"Advanced", topic:"Identity & Logins", prompt:"Which most helps detect password spraying?", options:["Monitoring for many accounts failing with the same password pattern","Installing a much faster main processor","Switching to a far brighter monitor screen","Adding a whole lot more free disk space"], correct:0, explain:"A pattern of many accounts seeing the same failed password hints at spraying.", reward:"Spray Defense" },
  { id:"identity-logins-058", tier:"Advanced", topic:"Identity & Logins", prompt:"Why avoid giving all staff admin rights 'just in case'?", options:["Broad access simply looks a bit bad","Excess privilege widens the damage if any account is compromised","Broad access is generally rather slow","It uses up a lot more storage space"], correct:1, explain:"Broad admin rights increase risk; grant elevated access only where truly needed.", reward:"Least Privilege" },
  { id:"identity-logins-059", tier:"Advanced", topic:"Identity & Logins", prompt:"How can conditional access reduce risk from stolen credentials?", options:["It speeds up every single login attempt","It hides all of the account usernames","It helps the cloud server save power","It can block or challenge logins that look risky or out of pattern"], correct:3, explain:"By challenging risky logins, conditional access can stop misuse of stolen credentials.", reward:"Conditional Sense" },
  { id:"identity-logins-060", tier:"Advanced", topic:"Identity & Logins", prompt:"What is 'impossible travel' in login monitoring?", options:["Going away on a long and relaxing vacation","A delayed or cancelled airline flight back home","Logins from distant places too close in time to be the same person traveling","Running a routine scheduled data backup job"], correct:2, explain:"Two logins far apart within minutes suggest stolen credentials, not real travel.", reward:"Login Watch" },
  { id:"identity-logins-061", tier:"Intermediate", topic:"Identity & Logins", prompt:"Which factor type is a fingerprint in authentication?", options:["Something you know","Something you are (biometric)","Something you have","Something you see"], correct:1, explain:"A fingerprint is a biometric, 'something you are', one of the authentication factor types.", reward:"Auth Basics" },
  { id:"identity-logins-062", tier:"Intermediate", topic:"Identity & Logins", prompt:"Granting a user access to only the reports they own is an example of...?", options:["Authorization controlling resource access","Confirming identity with authentication","A routine data backup","A network firewall rule"], correct:0, explain:"Limiting which resources a user can reach is authorization in action.", reward:"Authz Sense" },
  { id:"identity-logins-063", tier:"Advanced", topic:"Identity & Logins", prompt:"Why are app-based or hardware MFA codes generally stronger than SMS codes?", options:["App codes simply look nicer","App codes are generally faster","SMS can be intercepted or SIM-swapped more easily","They use up less mobile data"], correct:2, explain:"SMS is more vulnerable to interception and SIM swapping than app or hardware tokens.", reward:"MFA Shield" },
  { id:"identity-logins-064", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should websites store password hashes instead of plain passwords?", options:["Mainly to help save some disk space","Mainly for a nicer-looking display","To speed up each login attempt","So a database leak doesn't reveal the actual passwords"], correct:3, explain:"Hashing means a stolen database doesn't directly expose users' real passwords.", reward:"Password Strength" },
  { id:"identity-logins-065", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why enable MFA on your password manager itself?", options:["It adds protection to the vault that holds all your other passwords","Mainly to slow the whole thing down a bit","Mainly to change the display color theme","To end up using much more storage space"], correct:0, explain:"Since the vault is so valuable, MFA adds critical extra protection to it.", reward:"Manager Habit" },
  { id:"identity-logins-066", tier:"Beginner", topic:"Identity & Logins", prompt:"Besides lockout, what else slows password guessing?", options:["Choosing a nicer screen font","Rate limiting and delays between attempts","Using a much bigger monitor","Adding a lot more disk space"], correct:1, explain:"Throttling and delays reduce how fast an attacker can try passwords.", reward:"Lockout Sense" },
  { id:"identity-logins-067", tier:"Advanced", topic:"Identity & Logins", prompt:"What is 'privilege escalation' from an identity point of view?", options:["A noticeably faster login process","Choosing a much nicer display theme","Running a routine scheduled backup","An account gaining higher access than it should have"], correct:3, explain:"Privilege escalation is when an account ends up with more access than intended.", reward:"Privilege Sense" },
  { id:"identity-logins-068", tier:"Beginner", topic:"Identity & Logins", prompt:"If two people have the same job, role-based access lets you...?", options:["Give them different random access","Give them no access at all","Give them the same role and thus the same permissions","Share one single account between them"], correct:2, explain:"Same-role users get the same permissions, keeping access consistent for a job function.", reward:"Role Sense" },
  { id:"identity-logins-069", tier:"Intermediate", topic:"Identity & Logins", prompt:"A risk of overly broad groups is...?", options:["Somewhat nicer-looking dashboards","Many users may gain access they don't actually need","Noticeably faster user logins","A bit less storage being used"], correct:1, explain:"Broad groups can over-grant access, violating least privilege.", reward:"Group Sense" },
  { id:"identity-logins-070", tier:"Advanced", topic:"Identity & Logins", prompt:"Why avoid using a personal admin account as a service account?", options:["A dedicated service account can be scoped, monitored, and rotated independently","Such a setup is generally a whole lot slower","Such a setup simply ends up looking quite bad","It uses up a whole lot more storage space here"], correct:0, explain:"Dedicated service accounts are easier to scope, audit, and rotate than a personal login.", reward:"Service Account Care" },
  { id:"identity-logins-071", tier:"Intermediate", topic:"Identity & Logins", prompt:"What can you usually do if you no longer trust an app you granted access via OAuth?", options:["Nothing","Reinstall the OS","Revoke its access token","Change your monitor"], correct:2, explain:"You can revoke the app's OAuth token to cut off its access without changing your password.", reward:"OAuth Sense" },
  { id:"identity-logins-072", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is enforcing MFA on the SSO login especially valuable?", options:["Mainly just to get nicer-looking themes","To deliberately slow down all logins","To end up using more storage space","It protects the single login that unlocks many applications"], correct:3, explain:"MFA on SSO guards the one credential that grants access to everything behind it.", reward:"SSO Sense" },
  { id:"identity-logins-073", tier:"Advanced", topic:"Identity & Logins", prompt:"What is 'session hijacking'?", options:["An attacker stealing or reusing a valid session to impersonate the user","A much faster everyday user login process","Running a routine scheduled backup method","Doing a simple account password reset"], correct:0, explain:"Session hijacking steals a live session, such as a cookie, to act as the logged-in user.", reward:"Session Sense" },
  { id:"identity-logins-074", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is the benefit of being able to revoke a token?", options:["Somewhat nicer-looking log files","You can cut off access immediately if it is compromised","A noticeably faster main processor","Quite a lot more free storage space"], correct:1, explain:"Revocation lets you invalidate a leaked or misused token right away.", reward:"Token Sense" },
  { id:"identity-logins-075", tier:"Advanced", topic:"Identity & Logins", prompt:"A 'keylogger' steals credentials by...?", options:["Backing up your important files","Cooling down the computer's CPU","Encrypting all of the disks","Recording the keys you type, including passwords"], correct:3, explain:"Keyloggers capture keystrokes to steal passwords as you type them.", reward:"Credential Guard" },
  { id:"identity-logins-076", tier:"Advanced", topic:"Identity & Logins", prompt:"An attacker with stolen password hashes can do what?", options:["Do nothing useful with them at all really","Only print them out onto some paper","Guess offline against the hashes at high speed without lockouts","Just email them off to someone else"], correct:2, explain:"Offline guessing against stolen hashes avoids lockouts and can be very fast.", reward:"Guess Defense" },
  { id:"identity-logins-077", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why does MFA help against password spraying?", options:["MFA speeds up every single login attempt","Even if a common password matches, the second factor blocks access","MFA hides all of the account usernames","It deletes the affected user accounts"], correct:1, explain:"MFA stops a sprayed-correct password from being enough on its own.", reward:"Spray Defense" },
  { id:"identity-logins-078", tier:"Intermediate", topic:"Identity & Logins", prompt:"Applying least privilege to logins involves regularly...?", options:["Reviewing and removing access that is no longer needed","Adding even more admin user accounts","Sharing passwords with other people","Disabling MFA for everyone at once"], correct:0, explain:"Periodic reviews trim unnecessary access, keeping accounts at least privilege.", reward:"Least Privilege" },
  { id:"identity-logins-079", tier:"Intermediate", topic:"Identity & Logins", prompt:"A conditional access policy might block logins from...?", options:["Approved office devices","The user's normal location","Unmanaged or untrusted devices","A trusted work laptop"], correct:2, explain:"Policies can deny access from untrusted or non-compliant devices to reduce risk.", reward:"Conditional Sense" },
  { id:"identity-logins-080", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why alert on logins at unusual hours for an account?", options:["Mainly for some nicer-looking dashboards","To deliberately slow down all the logins","To help the cloud server save more power","Off-hours access can indicate misuse, especially with other red flags"], correct:3, explain:"Unusual timing, combined with other signals, can point to account compromise.", reward:"Login Watch" },
  { id:"identity-logins-081", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is strong authentication important?", options:["It helps ensure only the right person can access an account","It makes the whole monitor screen brighter","It speeds up all of your daily typing","It cools down the computer's main CPU"], correct:0, explain:"Strong authentication keeps accounts accessible only to their legitimate owners.", reward:"Auth Basics" },
  { id:"identity-logins-082", tier:"Beginner", topic:"Identity & Logins", prompt:"Authorization happens...?", options:["Before any identity is known","After authentication, to decide permissions","Only while backups are running","It essentially never happens"], correct:1, explain:"First you authenticate to prove identity, then authorization decides what you can do.", reward:"Authz Sense" },
  { id:"identity-logins-083", tier:"Beginner", topic:"Identity & Logins", prompt:"Where is MFA most important to enable?", options:["On a basic pocket calculator","On a simple music player app","On a plain notepad text app","On important accounts like email and admin logins"], correct:3, explain:"Critical accounts such as email, admin, and finance benefit most from MFA's extra protection.", reward:"MFA Shield" },
  { id:"identity-logins-084", tier:"Beginner", topic:"Identity & Logins", prompt:"A good password practice is to...?", options:["Share it with coworkers","Write it on the monitor","Use a unique, strong password per account","Reuse one everywhere"], correct:2, explain:"Unique strong passwords per account limit the damage if one is exposed.", reward:"Password Strength" },
  { id:"identity-logins-085", tier:"Beginner", topic:"Identity & Logins", prompt:"A benefit of a password manager is that you only need to remember...?", options:["Every password","One strong master password","No passwords ever","Your username only"], correct:1, explain:"You remember one strong master password; the manager handles the rest.", reward:"Manager Habit" },
  { id:"identity-logins-086", tier:"Beginner", topic:"Identity & Logins", prompt:"Repeated failed logins on an account might indicate...?", options:["Someone trying to guess the password","A much faster CPU at work","Some minor screen display problem","Just a routine backup running"], correct:0, explain:"A burst of failed logins can signal a guessing or brute-force attempt worth investigating.", reward:"Lockout Sense" },
  { id:"identity-logins-087", tier:"Beginner", topic:"Identity & Logins", prompt:"A privileged account should be...?", options:["Shared widely with everyone","Used for absolutely everything","Protected carefully and used only when needed","Left without any password at all"], correct:2, explain:"Privileged accounts need strong protection and limited, purposeful use.", reward:"Privilege Sense" },
  { id:"identity-logins-088", tier:"Beginner", topic:"Identity & Logins", prompt:"A role like 'Accountant' would typically grant...?", options:["Full access to absolutely everything","No access to anything at all","Random and inconsistent access","The permissions that job needs, such as finance systems"], correct:3, explain:"A role grants the permissions appropriate to that job function.", reward:"Role Sense" },
  { id:"identity-logins-089", tier:"Beginner", topic:"Identity & Logins", prompt:"Removing a departing employee from all groups helps...?", options:["Revoke their access quickly and cleanly","Speed up the network","Brighten the screen","Cool the CPU"], correct:0, explain:"Removing group memberships cuts off the access those groups provided.", reward:"Group Sense" },
  { id:"identity-logins-090", tier:"Beginner", topic:"Identity & Logins", prompt:"A good practice for service account credentials is to...?", options:["Share them widely with staff","Store them securely and rotate them periodically","Print them out on paper","Just use something like '12345'"], correct:1, explain:"Service account secrets should be stored securely and rotated to limit exposure.", reward:"Service Account Care" },
  { id:"identity-logins-091", tier:"Beginner", topic:"Identity & Logins", prompt:"OAuth is mainly about...?", options:["Cooling down the computer hardware","Editing and retouching photo files","Designing large computer networks","Delegated, limited access between apps and accounts"], correct:3, explain:"OAuth handles delegated, scoped access so one app can act with limited rights on another.", reward:"OAuth Sense" },
  { id:"identity-logins-092", tier:"Beginner", topic:"Identity & Logins", prompt:"SSO mainly improves...?", options:["Overall CPU processing speed","The monitor's screen color","User convenience and centralized access control","The total disk storage size"], correct:2, explain:"SSO improves convenience and lets organizations centrally manage access.", reward:"SSO Sense" },
  { id:"identity-logins-093", tier:"Beginner", topic:"Identity & Logins", prompt:"Ending a session by logging out mainly does what?", options:["Speeds up the computer's main CPU","Stops further access until you authenticate again","Brightens the whole monitor screen","Deletes the entire user account"], correct:1, explain:"Logging out invalidates the session, requiring re-authentication to access again.", reward:"Session Sense" },
  { id:"identity-logins-094", tier:"Beginner", topic:"Identity & Logins", prompt:"If an access token leaks, a good response is to...?", options:["Revoke it and issue a new one","Just ignore it completely","Share it with the team","Print it out on paper"], correct:0, explain:"Treat a leaked token as compromised: revoke it and replace it.", reward:"Token Sense" },
  { id:"identity-logins-095", tier:"Beginner", topic:"Identity & Logins", prompt:"A good defense against credential theft is to...?", options:["Reuse the same passwords","Disable MFA everywhere","Use unique passwords and enable MFA","Share logins with others"], correct:2, explain:"Unique passwords plus MFA strongly reduce the impact of stolen credentials.", reward:"Credential Guard" },
  { id:"identity-logins-096", tier:"Beginner", topic:"Identity & Logins", prompt:"MFA helps against brute force because...?", options:["MFA speeds up each login attempt","MFA hides the whole login screen","It helps the cloud server save power","Even a guessed password still needs the second factor"], correct:3, explain:"MFA means a correctly guessed password alone won't grant access.", reward:"Guess Defense" },
  { id:"identity-logins-097", tier:"Beginner", topic:"Identity & Logins", prompt:"Password spraying mainly targets...?", options:["Many accounts with a few common passwords","One account with many passwords","The CPU","The monitor"], correct:0, explain:"Spraying spreads a few guesses across many accounts, unlike brute force on one account.", reward:"Spray Defense" },
  { id:"identity-logins-098", tier:"Beginner", topic:"Identity & Logins", prompt:"A new intern needs to view reports only. Least privilege means giving them...?", options:["Admin rights","View-only access to reports","Access to everything","No access at all"], correct:1, explain:"Least privilege grants the intern just view access to reports, nothing more.", reward:"Least Privilege" },
  { id:"identity-logins-099", tier:"Beginner", topic:"Identity & Logins", prompt:"Conditional access decisions are based on...?", options:["Which color the screen currently shows","How big the total disk storage is","Which display font has been chosen","Context like who, where, what device, and the risk level"], correct:3, explain:"Conditional access weighs contextual signals to allow, challenge, or block a login.", reward:"Conditional Sense" },
  { id:"identity-logins-100", tier:"Beginner", topic:"Identity & Logins", prompt:"Login monitoring mainly helps an organization...?", options:["Pick some new display themes","Speed up the computer CPUs","Detect and respond to suspicious access","Save some extra disk space"], correct:2, explain:"Monitoring logins enables early detection and response to suspicious access.", reward:"Login Watch" },
  { id:"identity-logins-101", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is using unique passwords for each account important?", options:["If one password is stolen, attackers cannot reuse it everywhere","It makes every login screen look the same","It prevents accounts from needing usernames","It removes the need to monitor logins"], correct:0, explain:"Unique passwords limit damage because one stolen password does not unlock every account.", reward:"Password Habit" },
  { id:"identity-logins-102", tier:"Beginner", topic:"Identity & Logins", prompt:"What is the main risk of password reuse?", options:["It makes passwords harder to remember","A breach of one service can expose access to other accounts","It prevents users from enabling MFA","It stops password managers from working"], correct:1, explain:"If the same password is reused, attackers can try it on other services after one breach.", reward:"Password Safety" },
  { id:"identity-logins-103", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a login attempt from an unusual country or region often worth checking?", options:["It always proves the user is traveling safely","It means the account password was updated","It may indicate stolen credentials or suspicious access","It confirms the device is fully patched"], correct:2, explain:"Unusual login locations can be a sign of account compromise, especially when they do not match normal behavior.", reward:"Login Watch" },
  { id:"identity-logins-104", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is MFA useful even when a password is stolen?", options:["It changes the username automatically","It removes all need for account monitoring","It makes the password impossible to guess later","It adds another proof step before access is allowed"], correct:3, explain:"MFA can block access when an attacker has only the password but not the second factor.", reward:"MFA Shield" },
  { id:"identity-logins-105", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a suspicious sign in login activity?", options:["Many failed attempts followed by a successful login","A user logging in from their usual device during work hours","A password manager filling a saved password on an expected site","A scheduled access review completed by an admin"], correct:0, explain:"Repeated failures followed by success can suggest password guessing or credential stuffing.", reward:"Login Watch" },
  { id:"identity-logins-106", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should shared accounts be avoided when possible?", options:["Shared accounts always have weaker passwords","They make it harder to know who performed an action","They prevent all users from logging in","They disable security logging by default"], correct:1, explain:"Shared accounts reduce accountability because actions cannot be tied clearly to one person.", reward:"Accountability" },
  { id:"identity-logins-107", tier:"Beginner", topic:"Identity & Logins", prompt:"What does account lockout help defend against?", options:["Normal successful logins from approved users","A user changing their own password","Repeated password guessing attempts","A scheduled access review"], correct:2, explain:"Lockout slows or stops repeated login attempts after too many failures.", reward:"Lockout Sense" },
  { id:"identity-logins-108", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should old accounts be disabled when no longer needed?", options:["They make password managers impossible to use","They prevent new accounts from being created","They improve all login speeds automatically","They can become unused entry points for attackers"], correct:3, explain:"Unused accounts may be forgotten, unmonitored, and abused if left active.", reward:"Account Hygiene" },
  { id:"identity-logins-109", tier:"Beginner", topic:"Identity & Logins", prompt:"What is an access review?", options:["A check to confirm users still need the permissions they have","A process that changes every user's password daily","A backup of login logs to external storage","A tool that removes all MFA requirements"], correct:0, explain:"Access reviews help remove permissions that are no longer needed.", reward:"Access Review" },
  { id:"identity-logins-110", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a privileged account?", options:["An account used only for reading public web pages","An account with elevated access, such as admin rights","An account with no password configured","An account that cannot create logs"], correct:1, explain:"Privileged accounts can perform sensitive actions and need stronger protection.", reward:"Privilege Sense" },
  { id:"identity-logins-111", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should admin accounts be used only when needed?", options:["Admin accounts cannot access important systems","Admin accounts always expire after one login","Reducing admin use lowers the chance that high privileges are abused","Using admin accounts prevents MFA prompts"], correct:2, explain:"Limiting admin use reduces risk if the account or session is compromised.", reward:"Privilege Discipline" },
  { id:"identity-logins-112", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a password reset attack risk?", options:["The user may choose a new password","A reset flow may be abused to take over an account","The account may receive a notification","The helpdesk may record a ticket"], correct:1, explain:"Weak reset processes can let attackers bypass normal authentication.", reward:"Reset Safety" },
  { id:"identity-logins-113", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should password reset requests be verified?", options:["Verification helps prevent attackers from taking over accounts through social engineering","Verification makes every password shorter","Verification disables account logging","Verification prevents users from using MFA"], correct:0, explain:"Reset requests should confirm the user's identity before changing access.", reward:"Reset Safety" },
  { id:"identity-logins-114", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a session timeout?", options:["A process for deleting old user accounts","A limit that ends a login session after inactivity or time","A backup copy of authentication logs","A method for sharing passwords between users"], correct:1, explain:"Session timeouts reduce risk from abandoned or long-lived sessions.", reward:"Session Sense" },
  { id:"identity-logins-115", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should session tokens be protected?", options:["They only store the user's display name","They cannot be used after login","A stolen token may let an attacker access a session without the password","They are never sent over networks"], correct:2, explain:"Session tokens can act like proof of login, so stealing them can enable session hijacking.", reward:"Token Sense" },
  { id:"identity-logins-116", tier:"Beginner", topic:"Identity & Logins", prompt:"What is session hijacking?", options:["Changing the account's display picture","Reviewing a user's access rights","Ending an inactive login session","Taking over an active session using stolen session data"], correct:3, explain:"Session hijacking abuses session data so an attacker can act as the logged-in user.", reward:"Session Defense" },
  { id:"identity-logins-117", tier:"Beginner", topic:"Identity & Logins", prompt:"What does 'permission creep' mean?", options:["A user slowly accumulates more access than they still need","A password becomes longer over time","An account gets locked after too many failures","A login page loads slowly"], correct:0, explain:"Permission creep happens when users keep old access after role or job changes.", reward:"Access Review" },
  { id:"identity-logins-118", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should permissions be removed when a role changes?", options:["Role changes automatically delete all logs","The old access may no longer be needed and can create risk","It prevents users from using strong passwords","It disables MFA for the new role"], correct:1, explain:"Removing unneeded permissions keeps access aligned with the user's current job.", reward:"Least Privilege" },
  { id:"identity-logins-119", tier:"Beginner", topic:"Identity & Logins", prompt:"What is an identity provider?", options:["A device that only stores network cables","A tool that encrypts local backups","A system that manages authentication for users and applications","A browser extension that blocks advertisements"], correct:2, explain:"An identity provider manages logins and identity information for services.", reward:"Identity Basics" },
  { id:"identity-logins-120", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a sign-in log useful for?", options:["Changing the user's screen theme","Replacing all endpoint monitoring","Automatically approving admin access","Reviewing who logged in, when, from where, and whether it succeeded"], correct:3, explain:"Sign-in logs help investigate suspicious access and account activity.", reward:"Login Watch" },
  { id:"identity-logins-121", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a failed login event?", options:["A login attempt that did not successfully authenticate","A completed password manager backup","A user closing a browser tab","A successful access review"], correct:0, explain:"Failed login events show attempts where authentication did not succeed.", reward:"Login Watch" },
  { id:"identity-logins-122", tier:"Beginner", topic:"Identity & Logins", prompt:"Why are repeated failed logins from many accounts suspicious?", options:["They always mean the network is offline","They may indicate password spraying or credential guessing","They prove every account is protected by MFA","They prevent attackers from trying again"], correct:1, explain:"Repeated failures across many accounts can suggest broad password attacks.", reward:"Spray Defense" },
  { id:"identity-logins-123", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a risky service account practice?", options:["Using a unique strong secret stored securely","Limiting the account to required permissions","Sharing the same service account across many unrelated systems","Monitoring the account's activity"], correct:2, explain:"Broadly shared service accounts are harder to control, rotate, and investigate.", reward:"Service Account Care" },
  { id:"identity-logins-124", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should service account secrets be rotated?", options:["Rotation makes all applications faster","Rotation removes the need for logging","Rotation guarantees no compromise ever happened","Rotation limits the lifetime of exposed or old credentials"], correct:3, explain:"Rotating secrets reduces risk from old or leaked credentials.", reward:"Secret Rotation" },
  { id:"identity-logins-125", tier:"Beginner", topic:"Identity & Logins", prompt:"What does 'deny by default' mean in access control?", options:["Access is blocked unless it is explicitly allowed","Every user starts as an administrator","Passwords are never required","All login attempts are ignored"], correct:0, explain:"Deny by default allows only approved access and blocks everything else.", reward:"Access Control" },
  { id:"identity-logins-126", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is impossible travel detection useful?", options:["It replaces all MFA controls","It can flag logins from distant locations that are unlikely for one user","It proves the user account was deleted","It prevents users from working remotely"], correct:1, explain:"Impossible travel can indicate stolen credentials if logins happen from locations too far apart too quickly.", reward:"Anomaly Detection" },
  { id:"identity-logins-127", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is credential stuffing?", options:["Trying many random passwords against one account","Forcing users to change their password monthly","Using leaked username/password pairs against other services","Creating a new user group for administrators"], correct:2, explain:"Credential stuffing abuses leaked credentials from one service on other services.", reward:"Credential Guard" },
  { id:"identity-logins-128", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is MFA fatigue a security concern?", options:["MFA prompts can never be approved by users","It only happens when users have no password","It prevents all attackers from using stolen passwords","Attackers may repeatedly push prompts until a user approves one by mistake"], correct:3, explain:"MFA fatigue attacks rely on users approving repeated prompts just to stop the annoyance.", reward:"MFA Defense" },
  { id:"identity-logins-129", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a safer response to repeated MFA push prompts?", options:["Deny the prompt and report it through the approved process","Approve one prompt to make the alerts stop","Disable MFA for the account permanently","Share the MFA code with the helpdesk chat"], correct:0, explain:"Unexpected MFA prompts should be denied and reported because they may indicate stolen credentials.", reward:"MFA Defense" },
  { id:"identity-logins-130", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is conditional access useful for risky sign-ins?", options:["It can require extra checks or block access based on risk signals","It makes all passwords visible to admins","It removes the need for access reviews","It lets every location bypass MFA"], correct:1, explain:"Conditional access can respond differently depending on device, location, risk, and user context.", reward:"Conditional Sense" },
  { id:"identity-logins-131", tier:"Intermediate", topic:"Identity & Logins", prompt:"What should be reviewed after a suspected account compromise?", options:["Only the user's desktop wallpaper","Only whether the user remembers logging in","Sign-ins, tokens, MFA changes, mailbox rules, permissions, and related activity","Only the account's display name"], correct:2, explain:"Compromise review should check identity activity, persistence, access, and possible misuse.", reward:"Account Investigation" },
  { id:"identity-logins-132", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why are mailbox forwarding rules important in account compromise cases?", options:["They prove the account was never accessed","They only affect calendar reminders","They prevent attackers from reading messages","Attackers may use them to secretly collect mail"], correct:3, explain:"Malicious forwarding rules can continue leaking emails after an account is compromised.", reward:"Mailbox Watch" },
  { id:"identity-logins-133", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a risky sign involving MFA settings?", options:["MFA factors are added, removed, or changed unexpectedly","The user completes a normal MFA prompt during login","The company documents MFA enrollment steps","An admin reviews MFA coverage"], correct:0, explain:"Unexpected MFA changes can indicate an attacker trying to control account recovery or access.", reward:"MFA Watch" },
  { id:"identity-logins-134", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should privileged accounts avoid normal daily browsing and email?", options:["Privileged accounts cannot open browsers","Reducing routine use lowers exposure to phishing and web threats","Privileged accounts cannot receive logs","Browsers automatically remove admin rights"], correct:1, explain:"Using admin accounts only for admin tasks reduces chances that phishing or web activity compromises high privileges.", reward:"Admin Hygiene" },
  { id:"identity-logins-135", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is just-in-time access?", options:["Permanent admin access for all users","A password that never expires","Access granted only when needed and often for a limited time","A login that skips authorization"], correct:2, explain:"Just-in-time access reduces standing privileges by granting temporary access only when needed.", reward:"Privilege Discipline" },
  { id:"identity-logins-136", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why are stale privileged accounts dangerous?", options:["They always belong to active administrators","They cannot be used after business hours","They are automatically monitored more closely","They may keep powerful access without active ownership or review"], correct:3, explain:"Unused privileged accounts can become hidden high-impact entry points.", reward:"Account Hygiene" },
  { id:"identity-logins-137", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a good investigation step for a suspicious successful login?", options:["Check source location, device, MFA result, user history, and follow-on activity","Assume it is safe because it succeeded","Delete the account immediately without review","Ignore it unless the user complains"], correct:0, explain:"A successful login still needs context to determine whether it matches normal behavior.", reward:"Login Investigation" },
  { id:"identity-logins-138", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is device compliance useful in access decisions?", options:["It proves the user knows the password","It can require devices to meet security standards before access is allowed","It removes the need for user identity","It prevents all malware infections automatically"], correct:1, explain:"Device compliance helps ensure access comes from managed, healthy, or approved devices.", reward:"Conditional Sense" },
  { id:"identity-logins-139", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a risky OAuth consent scenario?", options:["A trusted internal app requesting documented permissions","A user denying an unknown app's access request","An unknown app requesting broad access to mail, files, or profile data","An admin reviewing consent logs"], correct:2, explain:"OAuth consent abuse can grant malicious apps access without stealing the user's password.", reward:"OAuth Defense" },
  { id:"identity-logins-140", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should OAuth app permissions be reviewed?", options:["OAuth apps cannot access user data","All OAuth permissions are harmless by design","Reviewing permissions disables all applications","Apps may request more access than they need or become risky over time"], correct:3, explain:"Reviewing app permissions helps limit excessive or suspicious delegated access.", reward:"OAuth Defense" },
  { id:"identity-logins-141", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is session revocation useful after account compromise?", options:["It forces existing sessions to end so stolen tokens may stop working","It guarantees the password was never stolen","It removes the need to reset credentials","It deletes all audit logs for the account"], correct:0, explain:"Revoking sessions helps cut off attackers who already have valid session tokens.", reward:"Session Defense" },
  { id:"identity-logins-142", tier:"Intermediate", topic:"Identity & Logins", prompt:"What does a risky sign-in score usually represent?", options:["How quickly a user typed the password","An estimate that the login may be suspicious based on signals","The storage size of the user profile","The age of the user's laptop"], correct:1, explain:"Risk scores combine signals like location, device, behavior, and known threats to guide response.", reward:"Risk Sense" },
  { id:"identity-logins-143", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should emergency admin accounts be carefully controlled?", options:["They have no security impact","They only work for reading public pages","They are often highly privileged and may bypass normal controls","They cannot be logged"], correct:2, explain:"Emergency accounts can be necessary, but their power makes monitoring and control important.", reward:"Admin Hygiene" },
  { id:"identity-logins-144", tier:"Advanced", topic:"Identity & Logins", prompt:"A user has impossible travel, failed MFA prompts, and then a successful login. What should be prioritized?", options:["Treat the sequence as possible credential compromise and investigate account activity","Assume the login is safe because MFA eventually succeeded","Close the alert because failed prompts happened first","Only check the user's keyboard layout"], correct:0, explain:"The sequence suggests stolen credentials plus possible MFA abuse, so account activity should be scoped.", reward:"Account Investigation" },
  { id:"identity-logins-145", tier:"Advanced", topic:"Identity & Logins", prompt:"Why is identity evidence often critical after endpoint malware is found?", options:["Endpoint malware cannot affect user accounts","Malware may steal tokens or passwords and enable access beyond the device","Identity logs replace the need for endpoint logs","User accounts cannot be abused remotely"], correct:1, explain:"Malware can steal credentials or tokens, so identity activity must be reviewed for follow-on access.", reward:"Identity Correlation" },
  { id:"identity-logins-146", tier:"Advanced", topic:"Identity & Logins", prompt:"What does suspicious OAuth consent plus mailbox forwarding suggest?", options:["A normal password reset process","A printer driver installation issue","Possible account abuse that may persist through app access and mail collection","A successful backup verification event"], correct:2, explain:"OAuth access and forwarding rules can both support persistent account abuse.", reward:"OAuth Defense" },
  { id:"identity-logins-147", tier:"Advanced", topic:"Identity & Logins", prompt:"Why can disabling one compromised account be insufficient?", options:["Identity compromise cannot affect cloud services","Disabled accounts always remove all evidence","Only passwords matter in account compromise","Other sessions, tokens, OAuth grants, or related accounts may remain active"], correct:3, explain:"Account compromise response should include sessions, tokens, app grants, rules, and related access.", reward:"Account Investigation" },
  { id:"identity-logins-148", tier:"Advanced", topic:"Identity & Logins", prompt:"A service account suddenly authenticates from an unusual host and accesses new resources. What should defenders check?", options:["Whether the secret was exposed, the source host is compromised, and permissions were abused","Only whether the account display name changed","Only whether the login succeeded","Whether the service account has a profile picture"], correct:0, explain:"Service account anomalies can indicate exposed secrets or misuse from compromised infrastructure.", reward:"Service Account Care" },
  { id:"identity-logins-149", tier:"Advanced", topic:"Identity & Logins", prompt:"Why is correlating identity logs with endpoint logs powerful?", options:["It replaces all user interviews","It connects account activity with device behavior, malware, and user context","It proves every login is legitimate","It prevents all phishing emails"], correct:1, explain:"Correlation helps show whether suspicious logins align with malware, device compromise, or user behavior.", reward:"Identity Correlation" },
  { id:"identity-logins-150", tier:"Advanced", topic:"Identity & Logins", prompt:"What is the risk of long-lived access tokens?", options:["They expire too quickly for attackers to use","They cannot be logged by identity systems","They may remain useful to attackers for a long time if stolen","They always require password re-entry on each request"], correct:2, explain:"Long-lived tokens increase risk because stolen tokens may remain valid for extended periods.", reward:"Token Sense" },
  { id:"identity-logins-151", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should users avoid sharing passwords with coworkers?", options:["Shared passwords make access reviews easier","Shared passwords automatically enable stronger encryption","It removes accountability and can expose accounts to misuse","It prevents attackers from guessing the password"], correct:2, explain:"Password sharing makes it harder to know who performed an action and increases misuse risk.", reward:"Accountability" },
  { id:"identity-logins-152", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a strong sign that an account may be compromised?", options:["A normal login from the user's managed laptop","A password reset requested through an approved process","A user completing MFA during their usual workday","Successful login activity from an unfamiliar device and location"], correct:3, explain:"Unusual successful logins can indicate stolen credentials or session misuse.", reward:"Login Watch" },
  { id:"identity-logins-153", tier:"Beginner", topic:"Identity & Logins", prompt:"What is the purpose of account disablement after an employee leaves?", options:["To prevent the old account from being used after access is no longer needed","To make the user's password easier to remember","To preserve all permissions for future convenience","To automatically delete every file the user created"], correct:0, explain:"Disabling old accounts reduces the chance that unused access is abused later.", reward:"Account Hygiene" },
  { id:"identity-logins-154", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is a password manager useful?", options:["It removes all need for MFA","It helps users create and store unique strong passwords","It makes every website use the same password","It prevents all phishing attacks automatically"], correct:1, explain:"Password managers help store unique, strong passwords so users do not reuse weak ones.", reward:"Manager Habit" },
  { id:"identity-logins-155", tier:"Beginner", topic:"Identity & Logins", prompt:"What does an access request usually ask for?", options:["A change to the user's screen settings","A full backup of the user's device","Permission to use a system, app, role, or resource","A reset of all company passwords"], correct:2, explain:"Access requests ask for permissions to systems or resources, ideally with approval and justification.", reward:"Access Control" },
  { id:"identity-logins-156", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should access requests include a business reason?", options:["It makes passwords longer","It replaces the need for approval","It hides the request from audit logs","It helps reviewers decide whether the access is justified"], correct:3, explain:"A business reason helps approvers judge whether requested access is necessary.", reward:"Access Review" },
  { id:"identity-logins-157", tier:"Beginner", topic:"Identity & Logins", prompt:"What is the purpose of MFA enrollment?", options:["Registering a second factor so the user can prove identity beyond a password","Creating a shared password for the whole team","Disabling sign-in logs for the account","Giving every user administrator rights"], correct:0, explain:"MFA enrollment registers a second proof method such as an app, token, or hardware key.", reward:"MFA Shield" },
  { id:"identity-logins-158", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should MFA recovery methods be protected?", options:["Recovery methods only affect screen settings","Attackers may abuse weak recovery to regain account access","Recovery methods prevent all login monitoring","They are unrelated to authentication"], correct:1, explain:"If attackers control recovery methods, they may bypass or reset authentication protections.", reward:"MFA Defense" },
  { id:"identity-logins-159", tier:"Beginner", topic:"Identity & Logins", prompt:"What is an account owner?", options:["The person who designed the login page","The system that stores password hashes","The person or team responsible for the account's purpose and access","The browser that remembers the username"], correct:2, explain:"Account ownership helps determine who should approve access, review usage, and respond to issues.", reward:"Account Hygiene" },
  { id:"identity-logins-160", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should privileged roles be assigned carefully?", options:["Privileged roles cannot be audited","Privileged roles only affect visual settings","Privileged roles prevent users from changing passwords","They can allow sensitive actions that cause large impact if misused"], correct:3, explain:"Privileged roles can change systems, data, and access, so they need careful control.", reward:"Privilege Sense" },
  { id:"identity-logins-161", tier:"Beginner", topic:"Identity & Logins", prompt:"What does 'least privilege' reduce?", options:["The damage possible if an account is misused or compromised","The need for users to remember usernames","The number of logs produced by systems","The ability to use MFA"], correct:0, explain:"Least privilege limits accounts to needed permissions, reducing potential damage.", reward:"Least Privilege" },
  { id:"identity-logins-162", tier:"Beginner", topic:"Identity & Logins", prompt:"Why are temporary access grants useful?", options:["They make access permanent by default","They give access for a limited time instead of leaving it open forever","They disable all audit logs during the request","They remove the need for an approver"], correct:1, explain:"Temporary grants reduce long-term exposure by ending access after the need passes.", reward:"Access Control" },
  { id:"identity-logins-163", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a suspicious sign involving a password reset?", options:["The reset was requested through the expected helpdesk process","The user confirms the reset through approved verification","A reset occurs shortly before unusual login activity","The reset is logged with a normal ticket reference"], correct:2, explain:"A reset followed by unusual access may indicate account takeover or social engineering.", reward:"Reset Safety" },
  { id:"identity-logins-164", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should login alerts include the source IP address?", options:["Source IPs always identify the attacker by name","Source IPs replace the need for user context","Source IPs cannot be used in investigations","They help analysts compare the login source with normal activity"], correct:3, explain:"Source IPs help determine whether a login came from an expected or suspicious location.", reward:"Login Investigation" },
  { id:"identity-logins-165", tier:"Beginner", topic:"Identity & Logins", prompt:"What is an inactive account?", options:["An account that has not been used for a long time","An account that always requires MFA","An account with only read-only access","An account created through an approved process"], correct:0, explain:"Inactive accounts may be forgotten and should be reviewed or disabled if no longer needed.", reward:"Account Hygiene" },
  { id:"identity-logins-166", tier:"Beginner", topic:"Identity & Logins", prompt:"Why are inactive accounts risky?", options:["They always have stronger passwords","They may be unmonitored and still have usable access","They cannot be used by attackers","They automatically delete sign-in logs"], correct:1, explain:"Inactive accounts may remain usable while nobody actively notices suspicious activity.", reward:"Account Hygiene" },
  { id:"identity-logins-167", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a login anomaly?", options:["A normal login from an expected device","A planned password change by the user","A sign-in pattern that differs from expected behavior","A successful access review"], correct:2, explain:"Anomalies can include unusual location, device, time, frequency, or behavior.", reward:"Anomaly Detection" },
  { id:"identity-logins-168", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should login failures be reviewed with context?", options:["All failed logins are harmless","All failed logins prove compromise","Failed login logs are unrelated to security","They may reflect user mistakes or attack attempts depending on pattern"], correct:3, explain:"Single failures may be normal, but patterns can suggest guessing or spraying.", reward:"Login Watch" },
  { id:"identity-logins-169", tier:"Beginner", topic:"Identity & Logins", prompt:"What is account recovery?", options:["The process used to regain access when normal login is not possible","A method for deleting all sign-in logs","A way to remove MFA permanently","A backup copy of the user's documents"], correct:0, explain:"Account recovery restores access, so it must verify identity carefully.", reward:"Reset Safety" },
  { id:"identity-logins-170", tier:"Beginner", topic:"Identity & Logins", prompt:"Why can weak account recovery be dangerous?", options:["It makes passwords expire too quickly","Attackers may use it to take over accounts without knowing the password","It prevents password managers from working","It blocks all legitimate users permanently"], correct:1, explain:"Weak recovery flows can become a bypass around normal authentication.", reward:"Reset Safety" },
  { id:"identity-logins-171", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a device trust signal?", options:["The user's preferred browser font","The amount of free disk space","Information showing whether a device is known, managed, or compliant","The color theme selected by the user"], correct:2, explain:"Device trust signals help decide whether access should be allowed, challenged, or blocked.", reward:"Conditional Sense" },
  { id:"identity-logins-172", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is logging successful logins important?", options:["Only failed logins matter in investigations","Successful logins are always safe","Successful logins cannot be abused","Attackers often need successful logins after stealing credentials"], correct:3, explain:"Successful login records help detect and investigate unauthorized access.", reward:"Login Watch" },
  { id:"identity-logins-173", tier:"Beginner", topic:"Identity & Logins", prompt:"What does password expiration try to reduce?", options:["Long-term exposure from old or possibly leaked passwords","The usefulness of MFA","The number of usernames in a directory","The need for account ownership"], correct:0, explain:"Password expiration can limit old password exposure, though modern policy often emphasizes strong unique passwords and MFA.", reward:"Password Safety" },
  { id:"identity-logins-174", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should privileged actions be logged?", options:["Logging prevents every mistake automatically","Logs support investigation, accountability, and audit review","Logs remove the need for approvals","Logging makes admin accounts less privileged"], correct:1, explain:"Privileged action logs help show who changed what and when.", reward:"Accountability" },
  { id:"identity-logins-175", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a security group commonly used for?", options:["Changing the user's password hint","Saving the user's browser bookmarks","Assigning permissions to multiple users together","Replacing all role-based access controls"], correct:2, explain:"Groups simplify permission management by assigning access to a set of users.", reward:"Group Sense" },
  { id:"identity-logins-176", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is reviewing group membership important after a role change?", options:["Old group memberships may still grant access the user no longer needs","Groups cannot affect system access","Role changes automatically remove every old permission","Group membership is never logged"], correct:0, explain:"Group memberships often control access, so old memberships can create permission creep.", reward:"Access Review" },
  { id:"identity-logins-177", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a risky pattern in privileged group membership?", options:["Membership is reviewed on a regular schedule","Users are added permanently for short-term tasks and never removed","Membership changes require approval","Group changes are logged and monitored"], correct:1, explain:"Permanent privileged access for temporary work creates standing risk.", reward:"Privilege Discipline" },
  { id:"identity-logins-178", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why are sign-ins from unmanaged devices risky?", options:["Unmanaged devices always have faster internet","Unmanaged devices cannot reach cloud services","They may lack required security controls, monitoring, or compliance","They prevent users from entering passwords"], correct:2, explain:"Unmanaged devices may be missing protections expected for business access.", reward:"Conditional Sense" },
  { id:"identity-logins-179", tier:"Intermediate", topic:"Identity & Logins", prompt:"What should analysts check when a user reports unexpected MFA prompts?", options:["Only whether the user's phone battery is full","Only whether the user likes push notifications","Only the color of the authenticator app","Recent sign-in attempts, source locations, and whether credentials may be stolen"], correct:3, explain:"Unexpected MFA prompts can indicate an attacker has the password and is trying to get approval.", reward:"MFA Watch" },
  { id:"identity-logins-180", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should service account activity be baselined?", options:["Service accounts usually have predictable patterns that make anomalies easier to spot","Service accounts never create security risk","Baselines remove the need for secret rotation","Service accounts cannot authenticate from hosts"], correct:0, explain:"A baseline helps detect unusual source hosts, times, resources, or behavior.", reward:"Service Account Care" },
  { id:"identity-logins-181", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a suspicious service account pattern?", options:["The account authenticates from its documented server","The account suddenly logs in interactively from a user workstation","The account has a documented owner","The account is monitored by security tooling"], correct:1, explain:"Service accounts should usually behave predictably; interactive or unusual host logins can indicate misuse.", reward:"Service Account Care" },
  { id:"identity-logins-182", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why are token lifetimes important?", options:["Tokens cannot be stolen by attackers","Short tokens disable all authentication","Longer token lifetimes can extend the window of misuse if stolen","Token lifetime only changes the login page color"], correct:2, explain:"If a token is stolen, a longer lifetime may let it be abused for longer.", reward:"Token Sense" },
  { id:"identity-logins-183", tier:"Intermediate", topic:"Identity & Logins", prompt:"What does session revocation do after suspicious activity?", options:["It changes every group membership","It removes all historical sign-in logs","It prevents the account from ever being used again","It invalidates active sessions so stolen session access may stop"], correct:3, explain:"Revocation forces sessions to end, helping cut off stolen tokens or active attacker access.", reward:"Session Defense" },
  { id:"identity-logins-184", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is a new MFA method added after suspicious login activity concerning?", options:["It may indicate the attacker is trying to control future access","It proves the user changed their wallpaper","It disables all identity logs automatically","It prevents the account from receiving email"], correct:0, explain:"Attackers may add their own MFA method to maintain access after compromise.", reward:"MFA Watch" },
  { id:"identity-logins-185", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is the risk of broad OAuth consent?", options:["It prevents the app from reading any user data","An app may gain access to mail, files, or profile data beyond what is needed","It always requires the user's password every minute","It disables all app permissions"], correct:1, explain:"Overly broad OAuth permissions can expose sensitive data through delegated app access.", reward:"OAuth Defense" },
  { id:"identity-logins-186", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is reviewing app consent logs useful?", options:["Consent logs only show display settings","Consent logs cannot indicate security risk","They can reveal when users or admins granted access to applications","They replace all endpoint telemetry"], correct:2, explain:"Consent logs help identify suspicious or excessive app permissions.", reward:"OAuth Defense" },
  { id:"identity-logins-187", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a risky account delegation scenario?", options:["Delegation is documented and approved","Delegation is limited to a specific business need","Delegation is reviewed after a project ends","A user or app receives broad access without clear owner or review"], correct:3, explain:"Unclear broad delegation can create hidden access paths.", reward:"Access Control" },
  { id:"identity-logins-188", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why do analysts review mailbox rules after account compromise?", options:["Rules can silently forward, delete, or hide messages for attackers","Mailbox rules cannot affect email visibility","Only administrators can create mailbox rules","Mailbox rules prove no credentials were stolen"], correct:0, explain:"Malicious mailbox rules can support persistence, spying, or hiding attacker activity.", reward:"Mailbox Watch" },
  { id:"identity-logins-189", tier:"Intermediate", topic:"Identity & Logins", prompt:"What does risk-based authentication try to do?", options:["Allow every login without challenge","Adjust login requirements based on signals like location, device, and behavior","Disable all MFA when a user travels","Ignore suspicious sign-in patterns"], correct:1, explain:"Risk-based authentication can step up verification or block access when signals look suspicious.", reward:"Risk Sense" },
  { id:"identity-logins-190", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why are admin consent workflows useful?", options:["They let any app access all data automatically","They stop all users from logging in","They require review before apps get sensitive permissions","They remove all audit requirements"], correct:2, explain:"Admin consent workflows help prevent risky applications from gaining broad access without review.", reward:"OAuth Defense" },
  { id:"identity-logins-191", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is a sudden increase in failed logins against many accounts suspicious?", options:["It proves all users forgot their passwords at once","It only happens during approved maintenance","It prevents attackers from finding valid accounts","It may indicate password spraying or automated guessing"], correct:3, explain:"Broad failed-login patterns across accounts are common in password spraying.", reward:"Spray Defense" },
  { id:"identity-logins-192", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a useful response after confirmed token theft?", options:["Revoke sessions, reset credentials as needed, review app grants, and check follow-on activity","Only change the user's display name","Ignore the issue if the password was changed last month","Disable all logs to reduce noise"], correct:0, explain:"Token theft response should cut off sessions and check whether access was abused.", reward:"Token Sense" },
  { id:"identity-logins-193", tier:"Advanced", topic:"Identity & Logins", prompt:"A cloud account shows suspicious OAuth consent but no password failure spike. What should defenders consider?", options:["Only password attacks can compromise accounts","An attacker may have abused consent flow or social engineering rather than brute force","The account is safe because no failures occurred","OAuth activity cannot provide access to data"], correct:1, explain:"OAuth consent abuse can grant access without a noisy password attack.", reward:"OAuth Defense" },
  { id:"identity-logins-194", tier:"Advanced", topic:"Identity & Logins", prompt:"Why can identity compromise continue after malware is removed from an endpoint?", options:["Malware removal always resets all cloud tokens","Stolen credentials, tokens, or app grants may remain usable elsewhere","Endpoint cleanup deletes every account session automatically","Identity systems cannot be affected by endpoint malware"], correct:1, explain:"Endpoint cleanup does not automatically invalidate stolen identity material.", reward:"Identity Correlation" },
  { id:"identity-logins-195", tier:"Advanced", topic:"Identity & Logins", prompt:"What should defenders assess if a privileged user shows anomalous logins and new group changes?", options:["Only whether the user recognizes the login page","Only whether the workstation has enough disk space","Potential privilege abuse, scope of access, and downstream changes","Whether the browser theme changed"], correct:2, explain:"Privileged identity compromise can create broad impact, so group and permission changes must be scoped.", reward:"Privilege Investigation" },
  { id:"identity-logins-196", tier:"Advanced", topic:"Identity & Logins", prompt:"Why is correlating MFA events with sign-in events important?", options:["MFA events replace all sign-in logs","MFA prompts always prove the user approved correctly","Sign-ins cannot be suspicious if MFA exists","It shows whether prompts, approvals, denials, and logins line up logically"], correct:3, explain:"Correlating MFA and sign-ins helps detect prompt bombing, unusual approval, or bypass patterns.", reward:"MFA Investigation" },
  { id:"identity-logins-197", tier:"Advanced", topic:"Identity & Logins", prompt:"A service account secret is found in a public repository. What is the safest assumption?", options:["Treat it as exposed and rotate it, then review usage for abuse","Assume nobody saw it if the repo was deleted","Only change the secret name, not the value","Wait for a user complaint before investigating"], correct:0, explain:"Exposed secrets should be rotated and logs checked for possible misuse.", reward:"Secret Rotation" },
  { id:"identity-logins-198", tier:"Advanced", topic:"Identity & Logins", prompt:"Why can excessive standing privilege be dangerous even without active alerts?", options:["It creates unnecessary blast radius if an account is later compromised","It guarantees faster incident response","It blocks all unauthorized access automatically","It prevents password reuse"], correct:1, explain:"Standing privilege increases potential damage before any alert occurs.", reward:"Privilege Discipline" },
  { id:"identity-logins-199", tier:"Advanced", topic:"Identity & Logins", prompt:"What is the value of mapping account activity after a suspected compromise?", options:["It replaces containment actions entirely","It proves the user was at fault","It reveals what systems, data, and permissions may have been accessed","It prevents all future phishing"], correct:2, explain:"Activity mapping helps scope impact and decide containment, recovery, and notification needs.", reward:"Account Investigation" },
  { id:"identity-logins-200", tier:"Advanced", topic:"Identity & Logins", prompt:"Why should incident response include both endpoint and identity actions?", options:["Endpoint and identity issues are always unrelated","Identity actions replace malware containment","Endpoint cleanup alone invalidates all cloud access","Attackers may move from device compromise to account misuse or vice versa"], correct:3, explain:"Modern incidents often cross endpoint and identity boundaries, so both sides need review.", reward:"Identity Correlation" },
  { id:"identity-logins-201", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should users report unexpected login notifications?", options:["They may indicate someone is trying to access the account","They always mean the account is safe","They replace the need for MFA","They prevent password changes automatically"], correct:0, explain:"Unexpected login notifications can be early signs of account misuse or attempted compromise.", reward:"Login Watch" },
  { id:"identity-logins-202", tier:"Beginner", topic:"Identity & Logins", prompt:"What is the purpose of a username?", options:["To decide the user's screen brightness","To identify which account is trying to authenticate","To replace the need for a password","To block all failed login attempts"], correct:1, explain:"A username identifies the account; authentication then proves the user is allowed to use it.", reward:"Auth Basics" },
  { id:"identity-logins-203", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should login systems hide whether a username exists?", options:["It makes user support impossible","It disables password reset features","It can reduce account enumeration by attackers","It prevents users from logging in successfully"], correct:2, explain:"Generic login errors make it harder for attackers to confirm valid usernames.", reward:"Enumeration Defense" },
  { id:"identity-logins-204", tier:"Beginner", topic:"Identity & Logins", prompt:"What does account enumeration mean?", options:["Reviewing account permissions during an audit","Changing passwords for all users","Removing inactive accounts from a directory","Discovering which usernames or accounts are valid"], correct:3, explain:"Attackers may try to learn valid accounts before password attacks or phishing.", reward:"Enumeration Defense" },
  { id:"identity-logins-205", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is a strong password still useful when MFA is enabled?", options:["It reduces the chance attackers reach the MFA step in the first place","It disables the user's second factor","It prevents all phishing attempts automatically","It removes the need to monitor login activity"], correct:0, explain:"MFA is important, but strong passwords still reduce initial compromise attempts.", reward:"Password Strength" },
  { id:"identity-logins-206", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a password blacklist?", options:["A list of accounts with no permissions","A list of known weak or breached passwords that should not be used","A list of users allowed to bypass MFA","A list of approved admin actions"], correct:1, explain:"Password blacklists block commonly used, weak, or breached passwords.", reward:"Password Safety" },
  { id:"identity-logins-207", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should passwords not be stored in plain text?", options:["Plain text passwords cannot be typed by users","Plain text passwords are too long for databases","Anyone who accesses the storage could read and reuse them","Plain text passwords automatically expire every hour"], correct:2, explain:"Passwords should be protected with strong hashing so stored values are not directly reusable.", reward:"Password Safety" },
  { id:"identity-logins-208", tier:"Beginner", topic:"Identity & Logins", prompt:"What is password hashing used for?", options:["Sending the password to every application in clear text","Making the login page load faster","Allowing users to share one password safely","Storing a one-way representation of a password for verification"], correct:3, explain:"Hashing lets systems verify passwords without storing the original password directly.", reward:"Password Safety" },
  { id:"identity-logins-209", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a good reason to require MFA for administrators?", options:["Admin accounts have higher impact if compromised","Admin accounts never use passwords","MFA prevents all configuration mistakes","MFA removes the need for logging"], correct:0, explain:"Compromised admin accounts can cause major damage, so stronger authentication is important.", reward:"MFA Shield" },
  { id:"identity-logins-210", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should a user deny an MFA prompt they did not initiate?", options:["Denying it confirms the password is weak","The prompt may come from an attacker using stolen credentials","Denying it disables all future logins","Unexpected prompts are always part of system updates"], correct:1, explain:"Unexpected MFA prompts may mean someone else has the password and is trying to log in.", reward:"MFA Defense" },
  { id:"identity-logins-211", tier:"Beginner", topic:"Identity & Logins", prompt:"What is an authentication factor?", options:["A user's favorite application theme","The number of apps installed on a device","A proof type used to verify identity, such as something you know, have, or are","A backup of the user's home folder"], correct:2, explain:"Authentication factors include passwords, tokens, phones, biometrics, and similar proofs.", reward:"Auth Basics" },
  { id:"identity-logins-212", tier:"Beginner", topic:"Identity & Logins", prompt:"Which is an example of 'something you have' in authentication?", options:["A memorized password","A remembered security question answer","A username typed into a login form","A hardware security key or authenticator device"], correct:3, explain:"A hardware key or authenticator device is a possession factor.", reward:"MFA Shield" },
  { id:"identity-logins-213", tier:"Beginner", topic:"Identity & Logins", prompt:"Why are hardware security keys considered strong MFA?", options:["They can resist many phishing attempts better than simple codes","They make passwords visible to administrators","They allow anyone nearby to log in","They remove the need for account recovery planning"], correct:0, explain:"Security keys can bind authentication to the real site, reducing phishing risk.", reward:"MFA Shield" },
  { id:"identity-logins-214", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a risky recovery question answer?", options:["One stored in a password manager as a random value","One that can be guessed or found from public information","One that is unique and unrelated to real facts","One protected by the same policy as passwords"], correct:1, explain:"Answers based on public facts can be guessed through social media or OSINT.", reward:"Reset Safety" },
  { id:"identity-logins-215", tier:"Beginner", topic:"Identity & Logins", prompt:"What does account provisioning mean?", options:["Removing all users from a system","Blocking every failed login attempt forever","Creating or granting an account and its initial access","Deleting old authentication logs"], correct:2, explain:"Provisioning creates accounts and assigns the access needed for a role or task.", reward:"Account Lifecycle" },
  { id:"identity-logins-216", tier:"Beginner", topic:"Identity & Logins", prompt:"What does account deprovisioning mean?", options:["Adding users to more groups","Resetting the account's display color","Making every account permanent","Removing access when it is no longer needed"], correct:3, explain:"Deprovisioning removes or disables accounts and permissions when access should end.", reward:"Account Lifecycle" },
  { id:"identity-logins-217", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is timely deprovisioning important?", options:["It reduces the time old access remains usable after a user leaves or changes role","It makes password managers unnecessary","It prevents all future phishing emails","It deletes every file the user created"], correct:0, explain:"Old access should be removed quickly so abandoned accounts cannot be abused.", reward:"Account Hygiene" },
  { id:"identity-logins-218", tier:"Beginner", topic:"Identity & Logins", prompt:"What is an orphaned account?", options:["An account with MFA enabled","An account without a clear active owner or user","An account with a recently changed password","An account used only during business hours"], correct:1, explain:"Orphaned accounts are risky because nobody may be responsible for reviewing or disabling them.", reward:"Account Hygiene" },
  { id:"identity-logins-219", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should orphaned accounts be reviewed?", options:["They always belong to active administrators","They are guaranteed to have no permissions","They may retain access without ownership or monitoring","They automatically expire after one login"], correct:2, explain:"Accounts without owners may keep permissions and become hidden access paths.", reward:"Account Hygiene" },
  { id:"identity-logins-220", tier:"Beginner", topic:"Identity & Logins", prompt:"What is an access token?", options:["A printed badge used for office entry","A password hint shown on the login page","A backup copy of the user's password","Data that represents an approved authenticated session or delegated access"], correct:3, explain:"Access tokens can let applications access resources without sending the password again.", reward:"Token Sense" },
  { id:"identity-logins-221", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should access tokens have limited lifetime?", options:["Shorter lifetimes reduce how long a stolen token may be useful","They make all users administrators","They prevent account lockouts from working","They remove the need to verify applications"], correct:0, explain:"Limiting token lifetime reduces the window for misuse if a token is exposed.", reward:"Token Sense" },
  { id:"identity-logins-222", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a refresh token commonly used for?", options:["Changing the user's password every minute","Getting new access tokens without asking for the password each time","Deleting old sign-in logs from the identity provider","Blocking all suspicious sign-ins automatically"], correct:1, explain:"Refresh tokens allow continued access by obtaining new access tokens, so they must be protected.", reward:"Token Sense" },
  { id:"identity-logins-223", tier:"Beginner", topic:"Identity & Logins", prompt:"Why are refresh tokens sensitive?", options:["They only store the user's display name","They cannot affect access after login","They may allow continued access even after the original access token expires","They are only used for changing screen settings"], correct:2, explain:"If stolen, refresh tokens may help attackers maintain access until revoked or expired.", reward:"Token Sense" },
  { id:"identity-logins-224", tier:"Beginner", topic:"Identity & Logins", prompt:"What does logging out usually do?", options:["Deletes every login log","Changes the user's password","Removes the account from all groups","Ends the current session so it can no longer be used normally"], correct:3, explain:"Logging out ends the active session, though some tokens may require separate revocation.", reward:"Session Sense" },
  { id:"identity-logins-225", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should suspicious sessions be revoked?", options:["To cut off active access that may be controlled by an attacker","To hide the incident from audit logs","To approve all future login attempts","To prevent password managers from working"], correct:0, explain:"Session revocation helps stop active misuse when compromise is suspected.", reward:"Session Defense" },
  { id:"identity-logins-226", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is an MFA approval from an unusual location suspicious?", options:["MFA approvals cannot be logged","It may indicate the user approved an attacker-initiated prompt","MFA approval always proves the login is safe","Location is unrelated to identity risk"], correct:1, explain:"An approval tied to unusual context may indicate push fatigue or social engineering.", reward:"MFA Investigation" },
  { id:"identity-logins-227", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a suspicious pattern in password reset logs?", options:["A user reset through a verified process after opening a ticket","Several accounts reset through unusual channels near suspicious sign-ins","A helpdesk ticket records the reset approver","A reset followed by normal MFA enrollment by the same user"], correct:2, explain:"Unusual reset patterns can indicate account takeover attempts or helpdesk abuse.", reward:"Reset Safety" },
  { id:"identity-logins-228", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why are dormant accounts with privileges especially risky?", options:["They are usually watched more closely than active accounts","They can provide powerful access with little normal activity to compare against","They cannot be used for interactive login","They automatically rotate passwords daily"], correct:1, explain:"Privileged dormant accounts are attractive because misuse may be less noticeable.", reward:"Privilege Discipline" },
  { id:"identity-logins-229", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a useful control for temporary privileged access?", options:["Permanent membership in admin groups for convenience","No logging during emergency admin use","Time-limited approval with auditing and automatic removal","Shared passwords between all administrators"], correct:2, explain:"Time-limited privileged access reduces standing risk and creates a record of use.", reward:"Privilege Discipline" },
  { id:"identity-logins-230", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is privileged access management useful?", options:["It prevents all users from logging in","It removes the need for any administrators","It makes every account public","It controls, monitors, and limits high-risk administrative access"], correct:3, explain:"Privileged access management reduces the risk and impact of admin account misuse.", reward:"Privilege Discipline" },
  { id:"identity-logins-231", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a suspicious sign involving group membership changes?", options:["A user is added to a sensitive group outside the normal approval process","A documented access review removes old permissions","An approved onboarding process adds a user to a standard group","An admin reviews group membership on schedule"], correct:0, explain:"Unapproved sensitive group changes can indicate privilege abuse or compromise.", reward:"Group Watch" },
  { id:"identity-logins-232", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should changes to administrator groups be monitored closely?", options:["Admin group changes cannot affect security","They can grant powerful access that changes the environment's risk","Admin groups are only used for display settings","Monitoring them prevents all helpdesk calls"], correct:1, explain:"Membership in admin groups can allow broad system or data control.", reward:"Group Watch" },
  { id:"identity-logins-233", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a risky sign involving a new API key or app secret?", options:["It is created through an approved deployment process","It has a documented owner and rotation schedule","It appears unexpectedly after suspicious account activity","It is stored in an approved secrets manager"], correct:2, explain:"Unexpected secrets created after suspicious activity may support persistence or unauthorized app access.", reward:"Secret Watch" },
  { id:"identity-logins-234", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should app secrets be monitored and rotated?", options:["Secrets cannot be used by attackers","Secrets only affect screen settings","Rotation guarantees there was never compromise","Exposed secrets can allow app or service access until changed"], correct:3, explain:"App secrets are credentials; if exposed, attackers may use them until revoked or rotated.", reward:"Secret Rotation" },
  { id:"identity-logins-235", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a suspicious sign involving conditional access policy changes?", options:["A policy is changed to weaken MFA or allow risky access unexpectedly","A documented policy is reviewed by security","A policy blocks logins from unsupported locations","A change is approved through normal governance"], correct:0, explain:"Policy changes that weaken controls can create new access paths for attackers.", reward:"Conditional Watch" },
  { id:"identity-logins-236", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should identity policy changes be tied to change records?", options:["Change records hide policy changes from analysts","They provide approval context and help distinguish authorized work from suspicious changes","They disable all risky sign-ins automatically","They replace the need for technical logs"], correct:1, explain:"Change records help confirm whether a sensitive policy change was expected and approved.", reward:"Change Review" },
  { id:"identity-logins-237", tier:"Intermediate", topic:"Identity & Logins", prompt:"What does an unusual spike in password reset requests suggest?", options:["Every user probably chose stronger passwords","The login page is visually broken","Possible social engineering, account takeover attempts, or user confusion after an attack","Password resets cannot be abused"], correct:2, explain:"Reset spikes can indicate attacks against recovery processes or broad user impact.", reward:"Reset Safety" },
  { id:"identity-logins-238", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is reviewing device identifiers useful in suspicious sign-ins?", options:["Device IDs always identify the attacker by name","Only unmanaged devices can log in successfully","Device identifiers replace all user investigation","They help compare whether sign-ins come from known, managed, or new devices"], correct:3, explain:"Device identifiers help determine whether a login came from expected user equipment.", reward:"Device Trust" },
  { id:"identity-logins-239", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a useful question when reviewing a suspicious service account login?", options:["Is the source host, time, resource, and method normal for that service account?","Does the service account have a nice display name?","Was the login page color different?","How many browser tabs were open?"], correct:0, explain:"Service accounts should have predictable behavior, so source and resource context matter.", reward:"Service Account Care" },
  { id:"identity-logins-240", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should privileged actions require stronger evidence of approval?", options:["Privileged actions can cause wider impact if unauthorized","Approval evidence slows every safe action forever","Privileged actions cannot be logged","Approvals remove the need for least privilege"], correct:0, explain:"High-impact actions need clear approval and auditability.", reward:"Accountability" },
  { id:"identity-logins-241", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a suspicious sign involving login success after many failures?", options:["The account may have been guessed, sprayed, or brute-forced successfully","It proves the user typed carefully","It means all previous failures are irrelevant","It prevents the need for MFA review"], correct:0, explain:"Many failures followed by success can indicate a successful password attack.", reward:"Login Watch" },
  { id:"identity-logins-242", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why are identity logs important after phishing?", options:["Phishing never affects accounts","They can show whether credentials were used after the user interacted with the lure","They replace email investigation completely","They prove all links were harmless"], correct:1, explain:"Identity logs reveal whether stolen credentials were used and what access followed.", reward:"Phishing Investigation" },
  { id:"identity-logins-243", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a suspicious OAuth app behavior?", options:["The app requests only documented minimum permissions","The app is approved through admin review","The app requests broad mail or file access soon after a suspicious login","The app appears in an approved application catalog"], correct:2, explain:"Broad app access after suspicious login may indicate consent abuse.", reward:"OAuth Defense" },
  { id:"identity-logins-244", tier:"Advanced", topic:"Identity & Logins", prompt:"A user reports MFA prompts, then logs show a successful login and new mailbox rule. What should responders suspect?", options:["Possible account compromise with persistence through mailbox manipulation","A normal browser cache refresh","A completed device compliance check","A password manager software update"], correct:0, explain:"MFA prompts plus successful login and mailbox rule creation can indicate account takeover.", reward:"Mailbox Watch" },
  { id:"identity-logins-245", tier:"Advanced", topic:"Identity & Logins", prompt:"Why is it risky to rely only on password reset after account compromise?", options:["Password reset always disables every token automatically","Existing sessions, refresh tokens, app grants, or mailbox rules may remain active","Password reset prevents all future phishing","Identity compromise cannot persist after a password change"], correct:1, explain:"Full recovery may require session revocation, token review, app grant review, and persistence checks.", reward:"Account Investigation" },
  { id:"identity-logins-246", tier:"Advanced", topic:"Identity & Logins", prompt:"What should be assessed after unexpected admin consent is granted to an app?", options:["Only whether the user likes the app name","Permissions granted, users affected, app publisher, activity, and data accessed","Only whether the app icon looks professional","Whether the app changed the user's screen size"], correct:1, explain:"Admin consent can grant broad access, so scope and activity must be reviewed.", reward:"OAuth Defense" },
  { id:"identity-logins-247", tier:"Advanced", topic:"Identity & Logins", prompt:"Why is identity blast radius important?", options:["It describes how much damage an account compromise could cause through its permissions","It measures how fast the login page loads","It shows whether a password is easy to type","It counts how many devices are in the office"], correct:0, explain:"Blast radius helps prioritize controls and response around high-impact accounts.", reward:"Privilege Investigation" },
  { id:"identity-logins-248", tier:"Advanced", topic:"Identity & Logins", prompt:"What should defenders consider if a compromised account accessed sensitive files and then added OAuth grants?", options:["Only whether the file names are short","Potential data exposure plus persistent delegated access through the app","That OAuth grants cannot survive password changes","That file access proves the user was legitimate"], correct:1, explain:"Data access and app grants together may indicate both theft and persistence.", reward:"Identity Correlation" },
  { id:"identity-logins-249", tier:"Advanced", topic:"Identity & Logins", prompt:"Why is monitoring failed logins alone insufficient?", options:["Failed logins always identify the attacker","Successful logins, token use, app grants, and privilege changes may reveal compromise","Successful logins are never suspicious","Failed logins cannot indicate attacks"], correct:1, explain:"Attackers eventually need successful access, so defenders must review success and post-login activity too.", reward:"Login Investigation" },
  { id:"identity-logins-250", tier:"Advanced", topic:"Identity & Logins", prompt:"A privileged account authenticates from a new device, adds a user to an admin group, and creates an app secret. What is the best response focus?", options:["Only verify whether the account display name changed","Treat as potential privilege compromise and investigate access, changes, sessions, and secrets","Assume the activity is safe because the login succeeded","Ignore the app secret unless a user complains"], correct:1, explain:"The sequence combines privileged login, access change, and secret creation, requiring urgent investigation.", reward:"Privilege Investigation" },
  { id:"identity-logins-251", tier:"Beginner", topic:"Identity & Logins", prompt:"What is identity lifecycle management?", options:["Managing account creation, access changes, and removal over time","Changing every user's screen layout","Backing up all user documents daily","Blocking all users from logging in"], correct:0, explain:"Identity lifecycle management covers onboarding, role changes, access reviews, and deprovisioning.", reward:"Account Lifecycle" },
  { id:"identity-logins-252", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should new user accounts follow an approved onboarding process?", options:["It makes every user an administrator","It helps ensure access is correct, approved, and documented","It disables all login monitoring","It removes the need for passwords"], correct:1, explain:"Approved onboarding reduces mistakes and gives users the access they need without unnecessary permissions.", reward:"Account Lifecycle" },
  { id:"identity-logins-253", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a joiner-mover-leaver process?", options:["A network cable replacement plan","A password manager export format","A workflow for account access when people join, change roles, or leave","A method for disabling all MFA prompts"], correct:2, explain:"Joiner-mover-leaver processes manage access during hiring, role changes, and departure.", reward:"Account Lifecycle" },
  { id:"identity-logins-254", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is the 'mover' part of joiner-mover-leaver important?", options:["It changes the user's profile picture","It prevents users from using password managers","It deletes the user's account immediately","It updates access when a person's role changes"], correct:3, explain:"When roles change, old access should be removed and new required access should be granted.", reward:"Access Review" },
  { id:"identity-logins-255", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a directory service commonly used for?", options:["Storing and managing users, groups, devices, and access information","Creating random desktop wallpapers","Scanning files for malware only","Replacing all network firewalls"], correct:0, explain:"Directory services help centrally manage identities, groups, and related access data.", reward:"Identity Basics" },
  { id:"identity-logins-256", tier:"Beginner", topic:"Identity & Logins", prompt:"Why are groups useful in access management?", options:["They make every user share one password","They let access be managed for many users at once","They prevent all failed logins","They remove the need for user accounts"], correct:1, explain:"Groups simplify access management by assigning permissions to a collection of users.", reward:"Group Sense" },
  { id:"identity-logins-257", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a risky group management habit?", options:["Reviewing group owners regularly","Using groups for documented job roles","Adding users to broad groups without clear need","Removing access when users change roles"], correct:2, explain:"Broad group access without clear need creates unnecessary permissions and larger risk.", reward:"Group Watch" },
  { id:"identity-logins-258", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should sensitive groups have owners?", options:["Group ownership changes the user's password","Group owners remove all logging needs","Group owners make MFA unnecessary","Owners help approve, review, and justify membership"], correct:3, explain:"Clear ownership helps keep group membership accurate and accountable.", reward:"Group Watch" },
  { id:"identity-logins-259", tier:"Beginner", topic:"Identity & Logins", prompt:"What is an admin role?", options:["A role with elevated permissions for managing systems or settings","A user account with no access","A role that only changes screen brightness","A backup copy of a password"], correct:0, explain:"Admin roles allow sensitive management actions and should be tightly controlled.", reward:"Privilege Sense" },
  { id:"identity-logins-260", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should admin roles be reviewed often?", options:["Admin roles cannot be abused","They can create high impact if assigned incorrectly or forgotten","Reviews disable all admin logging","Admin roles only affect usernames"], correct:1, explain:"Frequent review helps remove unnecessary privileged access.", reward:"Privilege Discipline" },
  { id:"identity-logins-261", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a break-glass account?", options:["An account used only for changing passwords","A normal user account for daily email","An emergency account used when normal access methods fail","A shared account for every employee"], correct:2, explain:"Break-glass accounts provide emergency access and need strong monitoring and protection.", reward:"Admin Hygiene" },
  { id:"identity-logins-262", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should break-glass accounts be monitored?", options:["They cannot affect important systems","They should be used for daily browsing","They automatically expire after every login","They are powerful and should only be used in rare emergency situations"], correct:3, explain:"Break-glass account use should be rare, logged, and reviewed because of its high privileges.", reward:"Admin Hygiene" },
  { id:"identity-logins-263", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a normal reason for an account to be locked?", options:["Too many failed login attempts within a short period","A user opens an approved application","A password manager fills a saved login","An access review is completed"], correct:0, explain:"Account lockout commonly happens after repeated failed authentication attempts.", reward:"Lockout Sense" },
  { id:"identity-logins-264", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should account lockouts be monitored?", options:["Lockouts are never security-related","Repeated lockouts may indicate password guessing or user-impacting problems","Lockouts remove all need for MFA","Lockouts prove the account is compromised every time"], correct:1, explain:"Lockouts can be caused by user mistakes, broken services, or attacks, so context matters.", reward:"Login Watch" },
  { id:"identity-logins-265", tier:"Beginner", topic:"Identity & Logins", prompt:"What is credential hygiene?", options:["A visual redesign of the login page","A method for changing browser themes","Good practices for protecting, rotating, and reducing exposure of credentials","A backup process for user documents"], correct:2, explain:"Credential hygiene means keeping passwords, tokens, and secrets protected and current.", reward:"Credential Guard" },
  { id:"identity-logins-266", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should credentials not be stored in documents or chat messages?", options:["Documents cannot contain text","Chat messages cannot be searched","It makes passwords easier to rotate","They may be copied, exposed, searched, or read by unauthorized people"], correct:3, explain:"Credentials in documents or chats can spread and remain exposed long after use.", reward:"Credential Guard" },
  { id:"identity-logins-267", tier:"Beginner", topic:"Identity & Logins", prompt:"What is an account audit trail?", options:["A record of account activity and changes over time","A list of desktop shortcuts","A backup of personal photos","A way to disable sign-in logs"], correct:0, explain:"Audit trails help show what happened to an account and who performed actions.", reward:"Accountability" },
  { id:"identity-logins-268", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is audit logging important for identity systems?", options:["It blocks all phishing attempts automatically","It supports investigation, accountability, and compliance review","It prevents all passwords from being stolen","It removes the need for access approval"], correct:1, explain:"Identity audit logs show sign-ins, changes, approvals, and suspicious behavior.", reward:"Accountability" },
  { id:"identity-logins-269", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a suspicious identity change?", options:["A documented password reset requested by the user","An approved role assignment during onboarding","An unexpected MFA method, group change, or password reset","A normal login from a managed device"], correct:2, explain:"Unexpected identity changes can indicate takeover, privilege abuse, or persistence.", reward:"Identity Watch" },
  { id:"identity-logins-270", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should identity changes be tied to a ticket or approval?", options:["Approvals hide suspicious changes from logs","Tickets replace the need for monitoring","Tickets make MFA unnecessary","They help prove the change was expected and authorized"], correct:3, explain:"Approval records help distinguish legitimate administration from suspicious change activity.", reward:"Change Review" },
  { id:"identity-logins-271", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a common sign of account takeover?", options:["New unusual sign-ins, settings changes, or access from unfamiliar devices","A user logging in from their normal laptop","A planned password change with proper verification","A scheduled access review"], correct:0, explain:"Account takeover often shows unusual logins, changed settings, new rules, or suspicious activity.", reward:"Account Investigation" },
  { id:"identity-logins-272", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should users report password reset emails they did not request?", options:["Unexpected reset emails may indicate someone is trying to access the account","Reset emails always mean the account is safe","Reset emails disable MFA automatically","Reporting them deletes the user's account"], correct:0, explain:"Unexpected reset messages can be early signs of account takeover attempts.", reward:"Reset Safety" },
  { id:"identity-logins-273", tier:"Beginner", topic:"Identity & Logins", prompt:"What does a security question try to do?", options:["Change the user's account permissions","Remove the need for usernames","Help verify identity during recovery or reset","Disable all sign-in monitoring"], correct:2, explain:"Security questions are sometimes used as recovery checks, but weak answers can be guessed.", reward:"Reset Safety" },
  { id:"identity-logins-274", tier:"Beginner", topic:"Identity & Logins", prompt:"Why are real personal facts weak recovery answers?", options:["They make passwords longer","They prevent account recovery","They are always encrypted by default","They may be guessed from public information or social media"], correct:3, explain:"Recovery answers based on public facts can be discovered and abused.", reward:"Reset Safety" },
  { id:"identity-logins-275", tier:"Beginner", topic:"Identity & Logins", prompt:"What is an access request approver responsible for?", options:["Checking whether requested access is justified and appropriate","Sharing their own password with the requester","Disabling audit logs for the request","Granting administrator rights to everyone"], correct:0, explain:"Approvers help ensure access is necessary, documented, and not excessive.", reward:"Access Review" },
  { id:"identity-logins-276", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is access to identity administration portals high-risk?", options:["Such portals can change users, roles, policies, and authentication settings","They only display public documentation","They cannot affect user access","They are unrelated to cloud services"], correct:0, explain:"Identity admin portals can control authentication and authorization across many systems.", reward:"Privilege Investigation" },
  { id:"identity-logins-277", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a suspicious sign in privileged role activation?", options:["Activation is approved through a documented workflow","A privileged role is activated at an unusual time without clear justification","The activation has an expiration time","The admin records the business reason"], correct:1, explain:"Unusual privileged role activation can indicate compromise or unauthorized administration.", reward:"Privilege Watch" },
  { id:"identity-logins-278", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is reviewing role activation reason useful?", options:["It changes the account password","It helps determine whether privileged access had a legitimate purpose","It prevents the role from being logged","It disables session revocation"], correct:1, explain:"A business reason helps validate whether the activation matches expected work.", reward:"Change Review" },
  { id:"identity-logins-279", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a risky pattern in application permission requests?", options:["The application requests only what it needs","The application has a known owner","The application requests broad permissions unrelated to its purpose","The application is reviewed by administrators"], correct:2, explain:"Excessive permissions increase risk if the app is malicious, compromised, or misused.", reward:"OAuth Defense" },
  { id:"identity-logins-280", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should identity systems monitor new device registrations?", options:["Device registration cannot affect authentication","Only printers can be registered as devices","Device registration always proves the user is legitimate","Unexpected devices may be used to satisfy access policies or persist access"], correct:3, explain:"Attackers may register devices to meet conditional access requirements or maintain access.", reward:"Device Trust" },
  { id:"identity-logins-281", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a suspicious device registration pattern?", options:["A new device is registered shortly after unusual sign-in activity","A managed laptop is registered during normal onboarding","A device is documented in an asset system","A user registers a replacement phone through approved support"], correct:0, explain:"New devices after suspicious sign-ins can indicate attacker-controlled device enrollment.", reward:"Device Trust" },
  { id:"identity-logins-282", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should defenders review authentication method changes?", options:["Authentication methods cannot affect account security","Unexpected changes may give attackers control over login or recovery","Only password changes matter in identity attacks","Authentication methods are never logged"], correct:1, explain:"Changes to phone numbers, authenticators, or recovery methods can support account takeover.", reward:"MFA Watch" },
  { id:"identity-logins-283", tier:"Intermediate", topic:"Identity & Logins", prompt:"What does suspicious addition of a phone number to an account suggest?", options:["The account was automatically patched","The account no longer needs monitoring","Possible attacker control over MFA or recovery","The user changed their screen theme"], correct:2, explain:"An unexpected phone number can allow attackers to receive recovery or MFA messages.", reward:"MFA Watch" },
  { id:"identity-logins-284", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why are passwordless login methods still security-sensitive?", options:["They cannot be used by attackers","They remove all need for device protection","They never rely on identity systems","They can still be abused if devices, keys, or recovery flows are compromised"], correct:3, explain:"Passwordless methods reduce password risk but still require device, key, and recovery protection.", reward:"Passwordless Sense" },
  { id:"identity-logins-285", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is a user logging in successfully after denied MFA prompts suspicious?", options:["It may indicate a different factor was used, prompt fatigue succeeded later, or session/token misuse","Denied MFA prompts always prove the account is safe","Successful logins cannot be suspicious","MFA denial disables the account permanently"], correct:0, explain:"Denied prompts followed by success deserve investigation because the attacker may have found another path.", reward:"MFA Investigation" },
  { id:"identity-logins-286", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a useful identity hunting question?", options:["Which users changed their desktop wallpaper this week?","Which accounts had unusual successful logins, MFA changes, or privilege changes?","Which users have the most browser bookmarks?","Which apps use the largest font size?"], correct:1, explain:"Identity hunting looks for unusual access, authentication changes, and privilege activity.", reward:"Identity Hunting" },
  { id:"identity-logins-287", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should external guest accounts be reviewed?", options:["Guests are always safer than employees","Guest accounts cannot access business data","They may retain access after collaboration ends","Guests do not create sign-in logs"], correct:2, explain:"External accounts may keep access longer than needed if not reviewed.", reward:"Guest Access" },
  { id:"identity-logins-288", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a risky guest access pattern?", options:["Guest access is tied to a documented project","Guest permissions are time-limited","Guest accounts are reviewed by owners","Guests retain broad access after the project ends"], correct:3, explain:"Guest access should be limited, owned, and removed when no longer needed.", reward:"Guest Access" },
  { id:"identity-logins-289", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is separation of duties useful in identity administration?", options:["It reduces the chance one person can approve and perform risky changes alone","It removes all need for administrators","It prevents all compromised accounts","It disables access reviews"], correct:0, explain:"Separation of duties adds control by splitting high-risk actions across roles or approvals.", reward:"Accountability" },
  { id:"identity-logins-290", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a risky sign involving emergency access accounts?", options:["Use is rare, documented, and reviewed","An emergency account is used without incident context or follow-up review","The account is monitored and protected","The account has a documented owner"], correct:1, explain:"Emergency account use should be exceptional and reviewed because it usually has high privileges.", reward:"Admin Hygiene" },
  { id:"identity-logins-291", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should identity alerts be correlated with email security alerts?", options:["Email cannot be involved in identity attacks","Phishing may lead to credential theft and later suspicious sign-ins","Identity logs replace all email evidence","Email alerts cannot include useful timing"], correct:2, explain:"Linking email and sign-in data helps connect phishing delivery to account compromise.", reward:"Phishing Investigation" },
  { id:"identity-logins-292", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a useful metric for identity defense?", options:["Number of users with unnecessary privileged access","Number of desktop icons per user","Average monitor brightness","Number of browser themes installed"], correct:0, explain:"Tracking excessive privilege helps reduce identity risk over time.", reward:"Privilege Discipline" },
  { id:"identity-logins-293", tier:"Advanced", topic:"Identity & Logins", prompt:"A user has a suspicious OAuth grant, new inbox rule, and external file access. What should defenders investigate?", options:["Possible persistent account compromise and data exposure through delegated access","Only whether the user's password is long enough","Whether the user changed their profile photo","Whether the login page loaded quickly"], correct:0, explain:"OAuth grants, inbox rules, and file access together suggest account misuse and possible data exposure.", reward:"Identity Correlation" },
  { id:"identity-logins-294", tier:"Advanced", topic:"Identity & Logins", prompt:"Why can guest accounts complicate incident response?", options:["Guests always have no access","Ownership, visibility, and offboarding may be weaker than for employees","Guest accounts cannot authenticate remotely","Guest activity is never logged"], correct:1, explain:"External identities may have unclear ownership or leftover access, making scoping harder.", reward:"Guest Access" },
  { id:"identity-logins-295", tier:"Advanced", topic:"Identity & Logins", prompt:"What should defenders consider when a new device registration follows credential theft malware?", options:["Whether stolen credentials were used to establish trusted-device access","Only whether the device name is short","That device registration proves the user is safe","That malware cannot affect identity systems"], correct:0, explain:"Credential theft plus new device registration can show attackers trying to satisfy access controls.", reward:"Device Trust" },
  { id:"identity-logins-296", tier:"Advanced", topic:"Identity & Logins", prompt:"Why should privileged identity incidents include downstream change review?", options:["Privileged accounts cannot change other accounts","Only the login itself matters","Attackers may have changed roles, groups, secrets, policies, or app grants","Downstream changes are unrelated to identity compromise"], correct:2, explain:"A privileged compromise can create many hidden persistence or access changes.", reward:"Privilege Investigation" },
  { id:"identity-logins-297", tier:"Advanced", topic:"Identity & Logins", prompt:"What is the danger of treating an identity alert as resolved after one password reset?", options:["The attacker may still have active sessions, refresh tokens, app grants, or changed recovery methods","Password reset always deletes every token","Password reset removes all mailbox rules automatically","Identity alerts cannot involve persistence"], correct:0, explain:"Account recovery must check sessions, tokens, app permissions, recovery settings, and persistence mechanisms.", reward:"Account Investigation" },
  { id:"identity-logins-298", tier:"Advanced", topic:"Identity & Logins", prompt:"Why is a conditional access bypass or exclusion high-risk?", options:["It can create a path around important authentication or device controls","It makes all access more secure automatically","It prevents attackers from using valid credentials","It disables all login attempts for administrators"], correct:0, explain:"Bypasses and exclusions can weaken protections for important users or locations.", reward:"Conditional Watch" },
  { id:"identity-logins-299", tier:"Advanced", topic:"Identity & Logins", prompt:"A compromised user had access to finance data, mailbox forwarding, and cloud storage. What should response include?", options:["Only resetting the user's desktop settings","Scoping data exposure, revoking sessions, removing persistence, and reviewing related access","Ignoring storage logs if email was involved","Closing the case after one password change"], correct:1, explain:"Identity compromise response must consider data access, persistence, sessions, and related systems.", reward:"Account Investigation" },
  { id:"identity-logins-300", tier:"Advanced", topic:"Identity & Logins", prompt:"Why is identity threat modeling useful?", options:["It replaces all monitoring and response","It helps identify likely abuse paths through accounts, roles, tokens, and trust relationships","It guarantees no user will be phished","It removes the need for access reviews"], correct:1, explain:"Identity threat modeling helps defenders understand where attackers could abuse access paths.", reward:"Identity Strategy" },
  { id:"identity-logins-301", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is a login from a new device worth reviewing?", options:["It may be normal, but it can also indicate access from an unrecognized device","New devices always prove the user is traveling","Device changes prevent all suspicious activity","New devices cannot be used with stolen credentials"], correct:0, explain:"A new device is not always malicious, but it is useful context for judging whether a login is expected.", reward:"Device Trust" },
  { id:"identity-logins-302", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a trusted device?", options:["A device with the brightest display settings","A device known, managed, or approved by the organization","A device that never needs authentication","A device used only for personal browsing"], correct:1, explain:"Trusted devices are known or managed in a way that supports safer access decisions.", reward:"Device Trust" },
  { id:"identity-logins-303", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should personal devices be treated carefully for business access?", options:["Personal devices always have better security controls","Personal devices cannot reach cloud apps","They may lack company monitoring, patching, or compliance controls","They automatically disable MFA"], correct:2, explain:"Personal devices may not meet the same security baseline as managed work devices.", reward:"Conditional Sense" },
  { id:"identity-logins-304", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a conditional access policy?", options:["A password list stored in a browser","A backup copy of user permissions","A report of old user accounts","A rule that allows, blocks, or challenges access based on conditions"], correct:3, explain:"Conditional access uses signals like user, location, device, risk, and app to decide what happens during login.", reward:"Conditional Sense" },
  { id:"identity-logins-305", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should risky sign-ins be investigated?", options:["They may show access attempts that do not match normal user behavior","They always mean the user forgot a password","They prove the account is already disabled","They replace the need for endpoint alerts"], correct:0, explain:"Risky sign-ins can reveal stolen credentials, suspicious devices, unusual locations, or attacker behavior.", reward:"Risk Sense" },
  { id:"identity-logins-306", tier:"Beginner", topic:"Identity & Logins", prompt:"What is an identity risk signal?", options:["A user's preferred desktop wallpaper","A clue such as unusual location, device, behavior, or known leaked credentials","A backup of the account profile","A guarantee that the login is malicious"], correct:1, explain:"Risk signals help identity systems judge whether access should be allowed, challenged, or investigated.", reward:"Risk Sense" },
  { id:"identity-logins-307", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should login time be considered during investigation?", options:["Time alone proves whether a login is malicious","Login time can be compared with the user's normal work pattern","Time replaces the need for source IP or device data","Every login outside office hours is harmless"], correct:1, explain:"Unusual login times may be suspicious when combined with other signals.", reward:"Login Investigation" },
  { id:"identity-logins-308", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a suspicious sign involving account profile changes?", options:["A user updates their job title through HR","A managed process updates contact details","The account is reviewed during onboarding","Recovery email, phone, or MFA details change unexpectedly"], correct:3, explain:"Unexpected recovery or MFA changes can indicate an attacker preparing persistence.", reward:"Identity Watch" },
  { id:"identity-logins-309", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should users avoid approving unexpected sign-in prompts?", options:["The prompt may be generated by an attacker trying to access the account","Approving always improves account security","Unexpected prompts are required for normal logout","Approving blocks the attacker permanently"], correct:0, explain:"Unexpected sign-in prompts can indicate stolen credentials being used by someone else.", reward:"MFA Defense" },
  { id:"identity-logins-310", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a phishing-resistant MFA method designed to reduce?", options:["The number of accounts in the directory","The chance that users approve or enter credentials for a fake site","The amount of audit logging available","The need to disable old accounts"], correct:1, explain:"Phishing-resistant methods help ensure authentication is tied to the real service, not a fake login page.", reward:"MFA Shield" },
  { id:"identity-logins-311", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should account recovery be logged?", options:["Recovery logs make passwords easier to guess","Recovery events are unrelated to security","Recovery can be abused and should be reviewable","Recovery logs prevent all user mistakes"], correct:2, explain:"Recovery logs help detect suspicious resets, changed methods, or takeover attempts.", reward:"Reset Safety" },
  { id:"identity-logins-312", tier:"Beginner", topic:"Identity & Logins", prompt:"What is one safe response to a suspected stolen password?", options:["Post the password in a team chat for review","Keep using the same password until the next audit","Disable all account logs","Reset the password and review related login activity"], correct:3, explain:"A suspected stolen password should be changed and related activity reviewed.", reward:"Password Safety" },
  { id:"identity-logins-313", tier:"Beginner", topic:"Identity & Logins", prompt:"What does password complexity usually try to improve?", options:["Resistance to guessing or cracking by requiring stronger password characteristics","The visual style of the login page","The speed of the user's internet connection","The number of open browser tabs"], correct:0, explain:"Complexity can make passwords harder to guess, especially when combined with length and uniqueness.", reward:"Password Strength" },
  { id:"identity-logins-314", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is password length important?", options:["Longer passwords are easier for attackers to reuse","Longer passwords usually create many more possible combinations","Longer passwords remove the need for MFA","Longer passwords are always stored in plain text"], correct:1, explain:"Length greatly increases the number of possible passwords an attacker must try.", reward:"Password Strength" },
  { id:"identity-logins-315", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a passphrase?", options:["A short one-character password","A password that must be shared with a coworker","A longer password made from multiple words or a memorable phrase","A backup code used only by administrators"], correct:2, explain:"Passphrases can be easier to remember while still being long and strong.", reward:"Password Strength" },
  { id:"identity-logins-316", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should backup MFA codes be stored carefully?", options:["Backup codes cannot unlock accounts","Backup codes are only used for changing wallpapers","Backup codes never expire in any system","They may allow account access if the normal MFA method is unavailable"], correct:3, explain:"Backup codes can act as emergency access, so they should be protected like passwords.", reward:"MFA Shield" },
  { id:"identity-logins-317", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a common purpose of login rate limiting?", options:["Slowing repeated authentication attempts to reduce guessing attacks","Making every login page load slower for all users","Preventing successful logins from being logged","Disabling passwords for all accounts"], correct:0, explain:"Rate limiting slows repeated attempts and makes guessing attacks harder.", reward:"Guess Defense" },
  { id:"identity-logins-318", tier:"Beginner", topic:"Identity & Logins", prompt:"Why are generic login error messages useful?", options:["They tell attackers exactly which usernames are valid","They reduce clues that help attackers enumerate accounts","They disable password reset completely","They prevent legitimate users from recovering access"], correct:1, explain:"Generic errors like 'invalid username or password' reveal less about which part was correct.", reward:"Enumeration Defense" },
  { id:"identity-logins-319", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a safe reason to review admin login history?", options:["To decide the admin's screen color","To check whether privileged access was expected and authorized","To delete every successful login record","To prevent all future password resets"], correct:1, explain:"Admin login history helps detect suspicious use of powerful accounts.", reward:"Admin Hygiene" },
  { id:"identity-logins-320", tier:"Beginner", topic:"Identity & Logins", prompt:"Why should accounts have clear owners?", options:["Ownership prevents all phishing attacks","Ownership replaces access reviews","Ownership helps decide who approves, reviews, and responds to account use","Ownership makes passwords unnecessary"], correct:2, explain:"Owners provide accountability for access, approvals, and ongoing review.", reward:"Account Hygiene" },
  { id:"identity-logins-321", tier:"Beginner", topic:"Identity & Logins", prompt:"What is an example of authorization?", options:["Proving identity with a password","Entering a one-time code","Allowing a user to read one folder but not another","Typing a username into a login form"], correct:2, explain:"Authorization decides what an authenticated identity can access or do.", reward:"Authz Sense" },
  { id:"identity-logins-322", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is authorization checked after authentication?", options:["Knowing who a user is does not automatically mean they can access everything","Authentication always grants full admin access","Authorization makes identity verification unnecessary","Authorization deletes old login sessions"], correct:0, explain:"After identity is verified, authorization decides what that identity is allowed to do.", reward:"Authz Sense" },
  { id:"identity-logins-323", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a risky permission assignment?", options:["Giving access based on job need","Granting broad access without a clear reason","Removing access after a project ends","Reviewing sensitive access regularly"], correct:1, explain:"Broad access without need increases the blast radius if an account is misused.", reward:"Least Privilege" },
  { id:"identity-logins-324", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is removing access after a project ends important?", options:["Project access cannot be abused","It reduces leftover permissions that are no longer needed","It deletes the user's normal account","It disables all future access requests"], correct:1, explain:"Temporary project access should not become permanent permission creep.", reward:"Access Review" },
  { id:"identity-logins-325", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a security benefit of SSO?", options:["SSO can centralize authentication and make access easier to monitor","SSO removes the need for strong identity controls","SSO makes every application public","SSO prevents users from ever logging out"], correct:0, explain:"SSO can improve visibility and policy enforcement by centralizing login control.", reward:"SSO Sense" },
  { id:"identity-logins-326", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why can SSO become high impact if misconfigured?", options:["SSO affects access to many connected applications","SSO cannot be logged by identity systems","SSO only works for local files","SSO prevents MFA from being used"], correct:0, explain:"A weakness in centralized SSO can affect many connected services.", reward:"SSO Sense" },
  { id:"identity-logins-327", tier:"Intermediate", topic:"Identity & Logins", prompt:"What does suspicious federation configuration require defenders to check?", options:["Only the login page logo","Trust relationships, certificates, domains, claims, and recent changes","Only the user's browser bookmarks","Whether the device has enough free disk space"], correct:1, explain:"Federation controls trust between identity systems, so changes can affect who can authenticate.", reward:"Federation Watch" },
  { id:"identity-logins-328", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is certificate or key rotation important in identity systems?", options:["Rotation changes every user's display name","Rotation removes the need for access reviews","Old keys or certificates may become exposed, weak, or no longer trusted","Certificates only affect desktop shortcuts"], correct:2, explain:"Rotating trust material reduces long-term risk from exposure or outdated keys.", reward:"Key Rotation" },
  { id:"identity-logins-329", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a suspicious sign in federation settings?", options:["A planned certificate update with change approval","A documented trusted domain used for business access","An unexpected trust or claim rule that grants access broadly","A normal metadata refresh from a known identity provider"], correct:2, explain:"Unexpected federation trust changes can create powerful access paths.", reward:"Federation Watch" },
  { id:"identity-logins-330", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should sign-in logs include application names?", options:["Application names help determine what resource was accessed","Application names make all logins safe","Application names replace user identity","Application names prevent failed logins"], correct:0, explain:"Knowing the app shows what service the account tried to access.", reward:"Login Investigation" },
  { id:"identity-logins-331", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is suspicious about a successful login followed by many access-denied events?", options:["The user may be probing resources they do not normally access","Access-denied events prove the user is safe","Successful logins cannot be suspicious","Access-denied events are never useful"], correct:0, explain:"After compromise, attackers may test access to resources and generate denied events.", reward:"Authorization Watch" },
  { id:"identity-logins-332", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should failed authorization events be reviewed?", options:["They can reveal probing, permission issues, or attempted access to restricted resources","They only show visual interface problems","They prevent all successful attacks","They are unrelated to identity monitoring"], correct:0, explain:"Authorization failures can show attempted access beyond normal permissions.", reward:"Authorization Watch" },
  { id:"identity-logins-333", tier:"Intermediate", topic:"Identity & Logins", prompt:"What does unusual access to many applications after one login suggest?", options:["The user only changed their password","Possible account misuse or automated exploration after compromise","The device is guaranteed compliant","The account has no permissions"], correct:1, explain:"Broad app access after login can indicate an attacker exploring what the account can reach.", reward:"Account Investigation" },
  { id:"identity-logins-334", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should defenders review password reset source information?", options:["The reset source can help distinguish expected helpdesk/user activity from suspicious activity","Source information prevents all account takeover attempts","Password reset source is never logged","Reset source replaces MFA review"], correct:0, explain:"Source context helps identify whether a reset came from an expected user, device, or process.", reward:"Reset Safety" },
  { id:"identity-logins-335", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a suspicious password reset source?", options:["A user's known managed device during a verified support case","An unfamiliar source shortly before unusual successful sign-ins","A documented helpdesk workflow with identity verification","A normal self-service reset after a user report"], correct:1, explain:"Unexpected reset source plus later suspicious access can indicate takeover.", reward:"Reset Safety" },
  { id:"identity-logins-336", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is reviewing deleted accounts useful after suspicious admin activity?", options:["Deleted accounts cannot be relevant to investigations","It may reveal cleanup, cover-up, or removal of unauthorized accounts","Account deletion proves the incident is resolved","Only active accounts can appear in logs"], correct:1, explain:"Attackers or careless admins may delete accounts to hide actions or remove traces.", reward:"Accountability" },
  { id:"identity-logins-337", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a suspicious pattern involving many newly created accounts?", options:["Approved onboarding for a documented training group","Accounts created through HR workflow","Bulk account creation without business context or ownership","Accounts assigned minimum needed permissions"], correct:2, explain:"Unexplained bulk account creation can indicate abuse or process failure.", reward:"Account Lifecycle" },
  { id:"identity-logins-338", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should account creation events include creator information?", options:["Creator information is only cosmetic","It helps determine who made the account and whether the creation was authorized","It prevents all attackers from creating accounts","It removes the need for approvals"], correct:1, explain:"Knowing who created an account supports accountability and investigation.", reward:"Accountability" },
  { id:"identity-logins-339", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a suspicious sign involving user impersonation features?", options:["Impersonation is limited and audited for support use","An account gains ability to act as another user without clear approval","Support actions are documented in a ticket","Impersonation is disabled by default"], correct:1, explain:"Impersonation can allow access as another user and must be tightly controlled.", reward:"Privilege Watch" },
  { id:"identity-logins-340", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is delegation in email or collaboration tools important to review?", options:["Delegation can grant others access to mailboxes, calendars, files, or actions","Delegation prevents all account compromise","Delegation only changes the user's display name","Delegation cannot be abused by attackers"], correct:0, explain:"Delegated access can expose sensitive data or allow actions on behalf of another user.", reward:"Delegation Watch" },
  { id:"identity-logins-341", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is a risky sign involving shared mailbox permissions?", options:["Access is assigned through an approved group","A user gains broad mailbox access without business justification","Shared mailbox access is documented","Access is removed after the project ends"], correct:1, explain:"Unjustified mailbox access can expose sensitive communications.", reward:"Mailbox Watch" },
  { id:"identity-logins-342", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why should identity monitoring include both humans and service accounts?", options:["Service accounts cannot be abused","Human users never create risk","Both can authenticate, access resources, and be misused if compromised","Only human accounts generate logs"], correct:2, explain:"Service accounts and human accounts can both become access paths for attackers.", reward:"Service Account Care" },
  { id:"identity-logins-343", tier:"Advanced", topic:"Identity & Logins", prompt:"A new federation trust appears without a change record. What should responders prioritize?", options:["Assume it is safe if users can still log in","Investigate trust configuration, source of change, affected apps, and possible unauthorized access","Only check whether the login page still loads","Delete all user accounts immediately"], correct:1, explain:"Unexpected federation trust changes can grant broad access and must be scoped carefully.", reward:"Federation Watch" },
  { id:"identity-logins-344", tier:"Advanced", topic:"Identity & Logins", prompt:"Why can access-token theft bypass normal password checks?", options:["Tokens may already represent an authenticated session or delegated permission","Tokens cannot be used by applications","Passwords are always required for every API request","Tokens only store cosmetic profile data"], correct:0, explain:"Tokens can allow access without re-entering the password, so token theft is serious.", reward:"Token Sense" },
  { id:"identity-logins-345", tier:"Advanced", topic:"Identity & Logins", prompt:"A user has no unusual password failures but has suspicious token use from a new device. What should be considered?", options:["The user must have typed the wrong password","Session or token theft may have occurred without a new password attack","Token use cannot be logged","The activity should be ignored because password failures are absent"], correct:1, explain:"Attackers may reuse stolen sessions or tokens without causing password failures.", reward:"Session Defense" },
  { id:"identity-logins-346", tier:"Advanced", topic:"Identity & Logins", prompt:"Why should defenders map trust relationships in identity incidents?", options:["Trust relationships determine which systems, apps, and tenants may accept an identity","Trust relationships only affect screen design","Trust maps replace log review","Trust relationships prevent all phishing"], correct:0, explain:"Trust relationships can expand incident scope beyond one account or application.", reward:"Identity Strategy" },
  { id:"identity-logins-347", tier:"Advanced", topic:"Identity & Logins", prompt:"Why is revoking sessions without removing malicious OAuth grants incomplete?", options:["OAuth grants cannot provide persistence","The app may still regain access through delegated permissions","Session revocation deletes all app permissions automatically","OAuth grants are unrelated to account misuse"], correct:1, explain:"OAuth grants can remain after session revocation, so both must be reviewed.", reward:"OAuth Defense" },
  { id:"identity-logins-348", tier:"Advanced", topic:"Identity & Logins", prompt:"A service account with broad permissions is used from a new workload. What is the best review focus?", options:["Only whether the workload has a friendly name","Secret exposure, workload legitimacy, permissions used, and affected resources","Only whether the login succeeded","Whether the service account has a profile picture"], correct:1, explain:"Service account changes require checking source, secret handling, permissions, and activity.", reward:"Service Account Care" },
  { id:"identity-logins-349", tier:"Advanced", topic:"Identity & Logins", prompt:"Why is least privilege harder in large environments?", options:["Access needs change over time, ownership gets unclear, and exceptions accumulate","Large environments do not use groups","Least privilege cannot apply to cloud systems","Users never change roles in large companies"], correct:0, explain:"Scale makes access drift more likely, so reviews and automation become important.", reward:"Least Privilege" },
  { id:"identity-logins-350", tier:"Advanced", topic:"Identity & Logins", prompt:"What does a mature identity investigation combine?", options:["Only failed login counts","Sign-ins, MFA, device, token, app consent, privilege, and endpoint context","Only the user's password age","Only whether the account is active"], correct:1, explain:"Good identity investigation correlates multiple signals instead of relying on one log type.", reward:"Identity Correlation" },

  { id:"identity-logins-351", tier:"Beginner", topic:"Identity & Logins", prompt:"What makes a passphrase a strong choice?", options:["A long secret made of several words that is easy to recall","A short code printed on the back of a bank card","A one-time number texted to your phone at login","A picture you draw to unlock a touchscreen"], correct:0, explain:"A passphrase strings several words together for length and memorability, making it strong yet easy to recall.", reward:"Password Strength" },
  { id:"identity-logins-352", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a one-time passcode (OTP)?", options:["A permanent password reused across every website","A short code that works only once for a single login","A printed list of all of your saved passwords","A backup copy of your account settings file"], correct:1, explain:"An OTP is valid for a single login or a short time, so a stolen reused password alone is not enough.", reward:"MFA Shield" },
  { id:"identity-logins-353", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a hardware security key?", options:["A spare house key kept at the office front desk","A license sticker placed on the laptop lid","A physical device used to prove your identity at login","A backup battery that powers the computer"], correct:2, explain:"A hardware security key is a small device that confirms your identity and resists phishing better than codes.", reward:"MFA Shield" },
  { id:"identity-logins-354", tier:"Beginner", topic:"Identity & Logins", prompt:"Why are backup codes provided when you enable MFA?", options:["They make the login screen load much faster","They replace the need to remember a password","They encrypt the whole hard drive automatically","They let you sign in if you lose your second factor"], correct:3, explain:"Backup codes are a safe fallback so you can still get in if your phone or token is unavailable.", reward:"MFA Shield" },
  { id:"identity-logins-355", tier:"Beginner", topic:"Identity & Logins", prompt:"What is the goal of account recovery?", options:["The process of regaining access to a lost account","Deleting an account that is no longer needed","Sharing one account between several coworkers","Renaming an account to something easier to type"], correct:0, explain:"Recovery lets a verified owner regain access, so it must be protected as strongly as login itself.", reward:"Recovery Sense" },
  { id:"identity-logins-356", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is using your email to reset many accounts a risk?", options:["Email resets always make passwords much weaker","If the email is compromised, many accounts can fall too","Email cannot be used to send reset links at all","Reset links make websites load more slowly"], correct:1, explain:"Email is a master key for resets, so securing it with MFA protects every account that relies on it.", reward:"Recovery Sense" },
  { id:"identity-logins-357", tier:"Beginner", topic:"Identity & Logins", prompt:"Why are shared logins discouraged?", options:["A login only one person could ever possibly use","An account that automatically expires each day","One login used by several people hurts accountability","An account that stores files for the whole team"], correct:2, explain:"Shared logins make it impossible to tell who did what, so each person should have their own account.", reward:"Access Control" },
  { id:"identity-logins-358", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a guest account typically for?", options:["Full administrator access for trusted senior staff","Permanent access identical to an employee account","A hidden account used only by outside attackers","Limited, temporary access for visitors or outsiders"], correct:3, explain:"Guest accounts grant minimal, time-limited access so visitors can do specific tasks without broad rights.", reward:"Access Control" },
  { id:"identity-logins-359", tier:"Beginner", topic:"Identity & Logins", prompt:"Why lock your computer when you step away?", options:["So nobody can use your open session while away","To make the computer charge its battery faster","To free up extra space on the hard drive","Backing up your most recent files automatically"], correct:0, explain:"An unlocked, unattended session lets anyone act as you, so locking it protects your access.", reward:"Session Sense" },
  { id:"identity-logins-360", tier:"Beginner", topic:"Identity & Logins", prompt:"What does enrolling in MFA mean?", options:["Turning off the password on your account","Registering a second factor like an app or key","Sharing your login with the help desk team","Resetting every password you currently use"], correct:1, explain:"Enrollment links a second factor to your account so future logins require more than a password.", reward:"MFA Shield" },
  { id:"identity-logins-361", tier:"Beginner", topic:"Identity & Logins", prompt:"Why avoid writing your password on a sticky note?", options:["It makes the password expire much sooner","It slows down how fast you can type it","Anyone passing by could read it and use it","A password manager would no longer work"], correct:2, explain:"A visible written password can be copied by anyone nearby; store secrets in a password manager instead.", reward:"Password Strength" },
  { id:"identity-logins-362", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a login-attempt log used for?", options:["Storing the full text of every email sent","Keeping a spare copy of the user files","Listing the websites a user has bookmarked","Reviewing who tried to sign in and when"], correct:3, explain:"Login logs help spot suspicious sign-in attempts and investigate possible account compromise.", reward:"Login Watch" },
  { id:"identity-logins-363", tier:"Beginner", topic:"Identity & Logins", prompt:"What is biometric authentication?", options:["Verifying identity using a trait like a fingerprint","Verifying identity by typing a longer password","Verifying identity using a mailed paper code","Verifying identity by answering a trivia question"], correct:0, explain:"Biometrics use something you are, such as a fingerprint or face, as an authentication factor.", reward:"Auth Basics" },
  { id:"identity-logins-364", tier:"Beginner", topic:"Identity & Logins", prompt:"Why be cautious with remember-me on a shared PC?", options:["It permanently deletes your saved password","It can keep you logged in for the next user","It makes the website refuse to load images","It always logs you out after one minute"], correct:1, explain:"On shared devices, staying signed in lets the next person reach your account, so avoid it there.", reward:"Session Sense" },
  { id:"identity-logins-365", tier:"Beginner", topic:"Identity & Logins", prompt:"Why change a device default password?", options:["A password the user picks during first setup","A password that never needs to be changed","A factory-set password attackers already know","A password that only works on weekends"], correct:2, explain:"Default passwords are public knowledge for many devices, so changing them is a basic first step.", reward:"Password Strength" },
  { id:"identity-logins-366", tier:"Beginner", topic:"Identity & Logins", prompt:"Why is reusing your work password on personal sites risky?", options:["Personal sites always load company pages slowly","Work passwords cannot be typed on personal sites","It makes your personal accounts expire sooner","A breach elsewhere could expose your work login"], correct:3, explain:"Password reuse means one breached site can hand attackers credentials that work elsewhere, including work.", reward:"Credential Guard" },
  { id:"identity-logins-367", tier:"Beginner", topic:"Identity & Logins", prompt:"What is self-service password reset?", options:["A safe way users reset their own password after verifying","A tool that shares passwords across the whole team","A feature that removes passwords from accounts","A list of every password used in the company"], correct:0, explain:"Self-service reset lets verified users recover access without the help desk while staying secure.", reward:"Recovery Sense" },
  { id:"identity-logins-368", tier:"Beginner", topic:"Identity & Logins", prompt:"Why are security questions like a pet name weak?", options:["Login pages would take longer to load","Their answers are often public or easy to guess","They can only be answered once every year","They replace the need for any real password"], correct:1, explain:"Personal trivia is often discoverable online, so it is a weak way to prove identity.", reward:"Auth Basics" },
  { id:"identity-logins-369", tier:"Beginner", topic:"Identity & Logins", prompt:"What does log-out-everywhere do?", options:["Deletes your account and all of its data","Changes your username on every website","Ends all your active sessions across devices","Turns off two-factor authentication for you"], correct:2, explain:"This invalidates every active session, useful if a device is lost or an account may be compromised.", reward:"Session Sense" },
  { id:"identity-logins-370", tier:"Beginner", topic:"Identity & Logins", prompt:"Why grant new staff access on their first day, not before?", options:["Accounts created early always run much faster","Early accounts use up more storage space","It makes the onboarding paperwork load quicker","Access should match an active, verified need"], correct:3, explain:"Granting access only when needed, and removing it when not, follows least privilege and limits risk.", reward:"Least Privilege" },
  { id:"identity-logins-371", tier:"Beginner", topic:"Identity & Logins", prompt:"What is a dormant account?", options:["An account not used for a long time","An account currently in heavy daily use","An account that belongs to an administrator","An account that stores team backup files"], correct:0, explain:"Unused accounts can be forgotten yet still valid, making them quiet, attractive targets for attackers.", reward:"Login Watch" },
  { id:"identity-logins-372", tier:"Beginner", topic:"Identity & Logins", prompt:"Why disable accounts of employees who leave?", options:["Disabled accounts make the network run faster","Former staff should not keep company access","It frees up colorful icons on the desktop","Leavers always forget their old passwords anyway"], correct:1, explain:"Promptly disabling leavers accounts prevents lingering access that could be misused or attacked.", reward:"Least Privilege" },
  { id:"identity-logins-373", tier:"Beginner", topic:"Identity & Logins", prompt:"Where is it safest to store many passwords?", options:["A plain text file saved on the desktop","A note taped under your keyboard tray","A reputable password manager with an encrypted vault","A shared spreadsheet emailed to the team"], correct:2, explain:"A password manager encrypts your credentials and lets you use a unique strong password everywhere.", reward:"Manager Habit" },
  { id:"identity-logins-374", tier:"Beginner", topic:"Identity & Logins", prompt:"What is just-in-time access in simple terms?", options:["Granting every user admin rights from day one","Keeping all access permanently switched on","Removing all access during business hours","Granting elevated access only when it is needed"], correct:3, explain:"Just-in-time access provisions higher privileges temporarily, then revokes them, shrinking the attack window.", reward:"Least Privilege" },
  { id:"identity-logins-375", tier:"Beginner", topic:"Identity & Logins", prompt:"Why review who has access to sensitive systems?", options:["People gather access over time they no longer need","Audits make the systems run noticeably faster","Reviews change everyone password automatically","Reviews add more storage to the file servers"], correct:0, explain:"Regular access reviews catch privilege creep, removing rights people picked up but no longer require.", reward:"Access Control" },
  { id:"identity-logins-376", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is SAML mainly used for?", options:["Encrypting files stored on a laptop disk","Letting one identity provider log users into many apps","Scanning a network for open ports","Backing up a database every night"], correct:1, explain:"SAML passes a trusted login assertion to applications, enabling single sign-on across them.", reward:"SSO Sense" },
  { id:"identity-logins-377", tier:"Intermediate", topic:"Identity & Logins", prompt:"What problem do passkeys aim to solve?", options:["Slow internet speeds on mobile devices","Running low on disk space on busy servers","Phishable passwords, using device-based crypto login","Screens that are too dim to read outdoors"], correct:2, explain:"Passkeys replace passwords with key pairs tied to your device, so there is no secret to phish or reuse.", reward:"Auth Basics" },
  { id:"identity-logins-378", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is SMS a weaker second factor than an app?", options:["Text messages always arrive far too slowly","Authenticator apps work without any device","SMS codes are far too long for users to type","Text codes can be intercepted or SIM-swapped"], correct:3, explain:"SMS can be redirected via SIM-swap or interception, while app and hardware factors avoid that channel.", reward:"MFA Shield" },
  { id:"identity-logins-379", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is step-up authentication?", options:["Asking for extra proof before a sensitive action","Lowering the password length requirement","Logging the user out after every click","Granting admin rights to every new user"], correct:0, explain:"Step-up auth requires extra verification for risky actions, even within an existing session.", reward:"Conditional Sense" },
  { id:"identity-logins-380", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is risk-based (adaptive) authentication?", options:["Using the same checks for every login always","Adjusting login checks based on location and device","Removing all checks for trusted employees","Charging users a fee for each failed login"], correct:1, explain:"Adaptive auth raises or lowers verification based on risk signals, challenging only unusual logins.", reward:"Conditional Sense" },
  { id:"identity-logins-381", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why are service accounts often higher risk?", options:["They are always protected by strong MFA","They can never be used by an attacker","They may have broad access and run unattended","They expire automatically every single day"], correct:2, explain:"Service accounts frequently hold broad rights, lack MFA, and run unattended, making them valuable targets.", reward:"Service Account Care" },
  { id:"identity-logins-382", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is segregation of duties?", options:["Giving one trusted person full end-to-end control","Letting everyone approve their own requests","Removing approvals entirely to speed work up","Splitting a sensitive task across two people"], correct:3, explain:"Separation of duties ensures one person cannot both request and approve, reducing fraud and error.", reward:"Access Control" },
  { id:"identity-logins-383", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is an access certification campaign?", options:["Managers periodically confirm needed access","A one-time grant of permanent admin rights","An automatic deletion of all user accounts","A scan that measures network bandwidth use"], correct:0, explain:"Access reviews have owners re-certify entitlements regularly so unneeded access is removed.", reward:"Access Control" },
  { id:"identity-logins-384", tier:"Intermediate", topic:"Identity & Logins", prompt:"What best describes an orphaned account?", options:["An account with an unusually strong password","An account whose owner has left or is gone","An account shared by an entire department","An account that has two-factor enabled"], correct:1, explain:"Orphaned accounts have no valid owner yet may still work, so they should be found and disabled.", reward:"Login Watch" },
  { id:"identity-logins-385", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is MFA fatigue (push bombing) a risk?", options:["Push notifications drain the server storage","Too many prompts speed up the login flow","Repeated prompts may get approved by mistake","Approvals make passwords expire instantly"], correct:2, explain:"Attackers spam approval prompts hoping a user taps accept; number matching helps counter this.", reward:"MFA Shield" },
  { id:"identity-logins-386", tier:"Intermediate", topic:"Identity & Logins", prompt:"What does number matching add to push MFA?", options:["Removing the need for any second factor","It sends the code by postal mail instead","It lets any tap approve the request quickly","The user enters a number shown on the login screen"], correct:3, explain:"Number matching forces the user to confirm a specific code, defeating blind approval of push spam.", reward:"MFA Shield" },
  { id:"identity-logins-387", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why check new passwords against breached lists?", options:["To stop users picking already-leaked passwords","To make the sign-up form load faster","To shorten how long passwords can be","To email each new password to the admin"], correct:0, explain:"Blocking known-breached passwords prevents reuse of credentials attackers already hold in their lists.", reward:"Password Strength" },
  { id:"identity-logins-388", tier:"Intermediate", topic:"Identity & Logins", prompt:"What best describes a break-glass account?", options:["A normal account every employee logs in with","An emergency admin account for when access fails","An account that self-destructs after one use","An account that only opens spreadsheets"], correct:1, explain:"Break-glass accounts are tightly controlled emergency logins, monitored closely and used only in crises.", reward:"Access Control" },
  { id:"identity-logins-389", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why limit how long a password reset link is valid?", options:["Long links always crash the email server","Short links are easier for users to memorize","A short expiry limits abuse of a stolen link","Expiring links make the password much stronger"], correct:2, explain:"Time-limiting reset links shrinks the chance an intercepted link is still usable by an attacker.", reward:"Recovery Sense" },
  { id:"identity-logins-390", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is a stolen session cookie dangerous?", options:["A stolen cookie speeds up the browser cache","A stolen cookie deletes your saved bookmarks","A stolen cookie changes the website theme","A stolen cookie can let an attacker resume your session"], correct:3, explain:"Session cookies prove you are logged in, so theft can continue your session without a password.", reward:"Token Sense" },
  { id:"identity-logins-391", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why prefer phishing-resistant MFA for admins?", options:["It resists fake login pages that capture codes","It is the cheapest option for every user","It removes the need to ever log in again","It makes admin tasks run much faster"], correct:0, explain:"Security keys verify the real site cryptographically, so a phishing page cannot relay the login.", reward:"MFA Shield" },
  { id:"identity-logins-392", tier:"Intermediate", topic:"Identity & Logins", prompt:"What is the purpose of an account lockout threshold?", options:["To delete the account after one wrong password","To stop rapid guessing after failed attempts","To make successful logins take much longer","To email the password to the user each time"], correct:1, explain:"Locking or delaying after repeated failures blocks brute-force guessing while balancing usability.", reward:"Lockout Sense" },
  { id:"identity-logins-393", tier:"Intermediate", topic:"Identity & Logins", prompt:"Why is a central identity directory helpful?", options:["Letting each app store its own separate passwords","It removes the need to monitor any logins","Access can be granted and revoked in one place","It makes every account share one password"], correct:2, explain:"A central directory means joiner, mover, and leaver changes apply everywhere, reducing stale access.", reward:"Access Control" },
  { id:"identity-logins-394", tier:"Advanced", topic:"Identity & Logins", prompt:"Why is OAuth an authorization framework, not authentication?", options:["It only stores passwords in plain text files","It encrypts hard drives for the operating system","It blocks all third-party apps from any access","It grants apps scoped access, not proof of identity"], correct:3, explain:"OAuth delegates access via scoped tokens; identity is layered on top, for example with OpenID Connect.", reward:"OAuth Sense" },
  { id:"identity-logins-395", tier:"Advanced", topic:"Identity & Logins", prompt:"Why scope OAuth tokens to the minimum needed?", options:["A leaked token can then do far less damage","Smaller scopes make the app load images faster","Broad scopes are required for any app to work","Scopes change the user password automatically"], correct:0, explain:"Least-privilege scopes limit what a stolen or misused token can reach, reducing blast radius.", reward:"OAuth Sense" },
  { id:"identity-logins-396", tier:"Advanced", topic:"Identity & Logins", prompt:"Why pair short-lived access tokens with refresh tokens?", options:["Both tokens are printed and mailed to the users","Short access tokens limit exposure while refresh renews","Long access tokens are always safer to use","Refresh tokens disable multi-factor entirely"], correct:1, explain:"Short access tokens cut the misuse window; a protected refresh token quietly renews access when valid.", reward:"Token Sense" },
  { id:"identity-logins-397", tier:"Advanced", topic:"Identity & Logins", prompt:"Why is binding a token to a device valuable?", options:["It makes tokens display in a much larger font","It lets any device reuse the same token freely","It ties a token to a device, resisting reuse","It removes the need to ever expire tokens"], correct:2, explain:"Binding a token to a device or key means a copied token will not work elsewhere, limiting theft impact.", reward:"Token Sense" },
  { id:"identity-logins-398", tier:"Advanced", topic:"Identity & Logins", prompt:"Why can SSO be a single point of failure?", options:["It always makes individual apps slower to load","SSO stores each app password on the desktop","SSO removes the need for any user accounts","Compromising SSO can unlock many connected apps"], correct:3, explain:"Because SSO unlocks many systems, its account needs strong, phishing-resistant MFA and monitoring.", reward:"SSO Sense" },
  { id:"identity-logins-399", tier:"Advanced", topic:"Identity & Logins", prompt:"Why automate the leaver step of identity lifecycle?", options:["Manual offboarding often misses access, leaving orphans","Automation makes the building lights turn off","Manual offboarding is always faster and safer","Automation deletes the company only backups"], correct:0, explain:"Automated deprovisioning removes access promptly across systems, avoiding lingering accounts after departure.", reward:"Least Privilege" },
  { id:"identity-logins-400", tier:"Advanced", topic:"Identity & Logins", prompt:"Why use continuous session evaluation after login?", options:["Logins should never be checked more than once","Risk can change mid-session, so re-check access","It removes the need for any password at all","It makes the browser cache pages forever"], correct:1, explain:"Conditions can shift after login, such as new location or device risk, so access may need re-verifying.", reward:"Conditional Sense" },
];

if (typeof module !== "undefined" && module.exports) module.exports = IDENTITY_LOGINS_QUESTIONS;
